(function(){
const DAY=()=>S.week*10+S.day;
const daily=k=>()=>S.flags['tx8_d_'+k]!==DAY()||t(`今天已经做过了，明天再来`,`Already done today — come back tomorrow`,`Já fizeste isto hoje — volta amanhã`);
const stamp=k=>{S.flags['tx8_d_'+k]=DAY()};
const once=k=>()=>!S.flags['tx8_'+k]||t(`这件事你已经做过了`,`You've already done this`,`Já fizeste isto`);
const SEAS=(a,b,z,e,p)=>()=>inSeason(a,b)||t(z,e,p);
const AND=(...f)=>()=>{for(const g of f){const r=g();if(r!==true)return r}return true};
const W=()=>(S.tripWith&&NPCS[S.tripWith])?S.tripWith:null;
const MET=id=>!!(S.npc[id]&&S.npc[id].met);
const ONL=n=>{S.online=clamp(S.online+n,0,100)};
const sc=(title,meta,text,choices)=>({title,meta,text,choices});
const P3=(zs,es,ps)=>{const i=Math.floor(Math.random()*zs.length);return t(zs[i],es[i],ps[i])};
const ST=k=>S.flags['tx8_'+k]||0;
const VIS=c=>(S.visited&&S.visited[c])||0;
const ADV=(k,c)=>{S.flags['tx8_'+k]=ST(k)+1;S.flags['tx8_'+k+'_v']=VIS(c)};
const STAGE=(k,c,max)=>()=>{if(ST(k)>=max)return daily(k)();const v=S.flags['tx8_'+k+'_v'];if(v!==undefined&&VIS(c)<=v)return t(`这一趟已经见过了，下次来再接着说`,`You've seen each other this trip — pick it up next visit`,`Já se viram nesta viagem — continuam na próxima visita`);return true};
const STORYTIP=t(`连续情节 · 每次来访推进一段`,`Ongoing story · one step each visit`,`História contínua · um passo por visita`);
function buy(title,ing,qty,mult,z,e,p){const c=cityBuy(ing,qty,mult);
 if(!c)return say(title,t(`你数了数钱包，这批货拿不下。`,`You count your cash. It won't cover the lot.`,`Contas o dinheiro. Não chega para o lote.`));
 return say(title,t(z,e,p),t(`${tt(ING[ing].n)} +${qty} · −$${c}`,`${tt(ING[ing].n)} +${qty} · −$${c}`,`${tt(ING[ing].n)} +${qty} · −$${c}`));}
function pop(title,max,mult,z,e,p){const r=popupSell(max,mult);
 if(!r.sold)return say(title,t(`你打开冷藏箱：空的。没带货出门，只好帮隔壁的摊子吆喝了一阵。`,`You open the cooler: empty. You came without stock, so you spend a while hollering for the next stall.`,`Abres a geleira: vazia. Vieste sem mercadoria, por isso passas um bocado a apregoar pela banca ao lado.`),t(`先在店里进货再出门`,`Stock up at the shop before you travel`,`Abastece o restaurante antes de viajar`));
 S.rep+=r.sold>=8?2:1;
 return say(title,t(z,e,p),t(`卖出 ${r.sold} 份 · +$${r.cash} · 口碑与线上评分上升`,`Sold ${r.sold} · +$${r.cash} · reputation and rating up`,`Vendeste ${r.sold} · +$${r.cash} · reputação e avaliação sobem`));}
const C={permian:t(`米德兰-敖德萨`,`Midland–Odessa`,`Midland–Odessa`),sanangelo:t(`圣安吉洛`,`San Angelo`,`San Angelo`),abilene:t(`阿比林`,`Abilene`,`Abilene`),delrio:t(`德尔里奥`,`Del Rio`,`Del Rio`)};

/* ---------------- JESSE (Permian Basin) ---------------- */
function jesseScene(){const s=ST('jesse'),T=t(`砂车司机`,`The sand hauler`,`O camionista da areia`);
 if(s===0)return sc(T,C.permian,[
  t(`20 号州际公路边的卡车停车场，凌晨四点。一排排拉砂的半挂车停着没熄火，车斗上盖着篷布，风一吹，细砂像烟一样从缝里漏出来。一辆车的驾驶室门开着，一个年轻人趴在方向盘上睡着了，手里还攥着一块没拆封的能量棒。`,`A truck stop off I-20, four in the morning. Rows of sand-hauling rigs idle with their tarps pulled tight, and when the wind gusts, fine sand leaks out of the seams like smoke. One cab door hangs open; a young man is asleep on the wheel, an unopened energy bar still in his fist.`,`Uma área de serviço de camiões junto à I-20, quatro da manhã. Filas de camiões de areia ao ralenti, com as lonas bem esticadas, e quando o vento sopra a areia fina escapa-se pelas costuras como fumo. Uma cabine tem a porta aberta; um rapaz dorme em cima do volante, ainda com uma barra energética por abrir na mão.`),
  t(`你敲了敲车门。他猛地坐直：“我没睡！我在等装货。”他最多二十二岁，眼睛红得像抽油机上的警示灯。“杰西，”他说，“敖德萨人。一天十四个小时，从沙丘矿拉到井场，再拉回来。”`,`You knock on the door. He jerks upright. "I wasn't sleeping! I'm waiting to load." He's twenty-two at most, eyes as red as the warning lamp on a pumpjack. "Jesse," he says. "Odessa born. Fourteen hours a day, dune mine to well pad and back again."`,`Bates na porta. Ele endireita-se de repente. «Não estava a dormir! Estou à espera de carregar.» Tem vinte e dois anos, no máximo, e os olhos vermelhos como a luz de aviso de uma bomba de petróleo. «Jesse», diz. «De Odessa. Catorze horas por dia, da mina das dunas ao poço e de volta.»`)],[
  {t:t(`从冷藏箱里拿出烤肉和面包给他`,`Hand him grilled meat and bread from your cooler`,`Dar-lhe carne grelhada e pão da tua geleira`),fx:()=>{rel('jesse').met=true;addLike('jesse',2);addTrust('jesse',1);stat('oficio',1);ADV('jesse','permian');log('在二叠纪盆地认识了砂车司机杰西','Met Jesse, a sand hauler, in the Permian Basin','Conheceste o Jesse, camionista de areia, na Bacia do Pérmico')},
   next:()=>say(T,t(`他吃得很快，像怕有人抢。吃完了才说：“我妈也这么腌肉，放大蒜放到人哭。”他把能量棒塞回口袋，“下次来，到莫纳汉斯沙丘找我。我带你看看这些砂是从哪儿来的。”`,`He eats fast, like someone might take it. Only when he's done does he say, "My mom marinates like that. Garlic till you cry." He pockets the energy bar. "Next time, find me out at the Monahans dunes. I'll show you where all this sand comes from."`,`Come depressa, como se alguém lho fosse tirar. Só no fim diz: «A minha mãe tempera assim. Alho até chorar.» Mete a barra no bolso. «Da próxima vez, procura-me nas dunas de Monahans. Mostro-te de onde vem esta areia toda.»`),t(`认识了杰西 · 好感 +2 · 信任 +1`,`Met Jesse · Liking +2 · Trust +1`,`Conheceste o Jesse · Afeição +2 · Confiança +1`))},
  {t:t(`问他：拉砂一趟能挣多少？`,`Ask him what a sand run pays`,`Perguntar quanto paga uma viagem de areia`),fx:()=>{rel('jesse').met=true;addLike('jesse',1);stat('tex',3);ADV('jesse','permian');log('在二叠纪盆地认识了砂车司机杰西','Met Jesse, a sand hauler, in the Permian Basin','Conheceste o Jesse, camionista de areia, na Bacia do Pérmico')},
   next:()=>say(T,t(`“好的时候比我爸当年在油井上挣得多。坏的时候，油价一跌，车贷还在。”他笑了一下，“这里就是这样：要么发财，要么搬走。我两样都还没干成。下次来，到莫纳汉斯沙丘找我。”`,`"Good times, more than my dad made on the rigs. Bad times, the oil price drops and the truck note doesn't." He grins. "That's the Basin: boom or bust. I ain't managed either yet. Next time, come find me out at the Monahans dunes."`,`«Nos bons tempos, mais do que o meu pai ganhava nas sondas. Nos maus, o petróleo cai e a prestação do camião não.» Sorri. «É assim a Bacia: ou enriqueces ou vais embora. Ainda não consegui nenhuma das duas. Da próxima vez, procura-me nas dunas de Monahans.»`),t(`认识了杰西 · 德州味 +3`,`Met Jesse · Texanness +3`,`Conheceste o Jesse · Texanidade +3`))}]);
 if(s===1)return sc(T,C.permian,[
  t(`莫纳汉斯沙丘在敖德萨往西，公路边突然冒出一片白色的沙海，像有人把海滩搬到了油田中间。杰西的车停在矿场外面排队，前面还有三十辆。“这些年他们发现，盆地里的沙丘砂就能用，不用从北边几个州拉过来。”他抓起一把砂，“压进地底下几千英尺，把石头里的油撑出来。”`,`The Monahans sandhills lie west of Odessa: suddenly, beside the highway, a white sea of dunes, as if someone had moved a beach into the middle of the oilfield. Jesse's rig waits in line outside a mine, thirty trucks ahead of him. "Few years back they figured out the dune sand right here works fine — no need to haul it down from up north." He scoops a handful. "Push it thousands of feet down, prop the rock open, let the oil out."`,`As dunas de Monahans ficam a oeste de Odessa: de repente, à beira da estrada, um mar branco de areia, como se alguém tivesse posto uma praia no meio do campo petrolífero. O camião do Jesse está na fila à porta de uma mina, com trinta à frente. «Há uns anos perceberam que a areia das dunas daqui serve, não é preciso trazê-la lá do norte.» Apanha uma mão-cheia. «Mete-se milhares de pés lá para baixo, abre-se a rocha, sai o petróleo.»`),
  t(`他压低声音：“下个月调度给我换了单子。不拉井场了，拉到东边，说是‘中部德州新中转站’，在 35 号州际公路边上。货主是一家新公司，叫孤星砂业。”你手里的砂一下子从指缝里漏光了。`,`He lowers his voice. "Next month dispatch is switching my loads. No more well pads — I'm hauling east, to some 'new Central Texas transload' off I-35. The shipper's a new outfit. Lone Star Sand." The sand in your hand runs out between your fingers all at once.`,`Baixa a voz. «No mês que vem o despacho muda-me as cargas. Acabaram-se os poços — vou levar para leste, para um tal "novo terminal do Texas Central" junto à I-35. O expedidor é uma empresa nova. Lone Star Sand.» A areia que tinhas na mão escorre-te toda de uma vez por entre os dedos.`),
  ...(S.flags.c3_lss?[t(`孤星砂业。罗兹在酒吧里拍在吧台上的那个名字。`,`Lone Star Sand. The name Roz slapped on the bar.`,`Lone Star Sand. O nome que a Roz atirou para cima do balcão.`)]:[t(`你不知道孤星砂业是谁，但“35 号州际公路边上”这几个字让你后背发凉。`,`You don't know who Lone Star Sand is, but "off I-35" sends a chill down your back.`,`Não sabes quem é a Lone Star Sand, mas «junto à I-35» dá-te um arrepio na espinha.`)])],[
  {t:t(`告诉他实话：你的店就在 35 号州际公路边上`,`Tell him the truth: your shop sits right off I-35`,`Dizer-lhe a verdade: o teu restaurante fica mesmo junto à I-35`),fx:()=>{addTrust('jesse',2);ADV('jesse','permian')},
   next:()=>say(T,t(`杰西看了你很久。“圣鲁伊斯？”他从仪表盘上拿起一张调度单，指着目的地：圣鲁伊斯，罐头厂路。“老天。”他把单子折起来，“下次来，我把这几个月的货单都带上。我妈说，拉别人的东西也要知道拉的是什么。”`,`Jesse studies you a long time. "San Luís?" He picks a dispatch sheet off the dash and points at the destination: San Luís, Packing Co. Road. "Lord." He folds it. "Next time you come, I'll bring the bills of lading from the last few months. My mom says even if you're hauling somebody else's load, you oughta know what it is."`,`O Jesse olha para ti muito tempo. «San Luís?» Tira uma folha de despacho do tablier e aponta o destino: San Luís, Packing Co. Road. «Meu Deus.» Dobra-a. «Da próxima vez trago as guias de transporte dos últimos meses. A minha mãe diz que mesmo a levar a carga dos outros tens de saber o que levas.»`),t(`杰西信任 +2 · 他会带来货单`,`Jesse trust +2 · He'll bring the paperwork`,`Confiança do Jesse +2 · Ele vai trazer os papéis`))},
  {t:t(`装作随便问问，套他的话`,`Play it casual and pump him for details`,`Fazer-te de desinteressado e puxar por ele`),req:()=>charm()>=45||NEED(t(`魅力 45`,`Charm 45`,`Charme 45`)),fx:()=>{flirt();addLike('jesse',1);stat('charme',1);ADV('jesse','permian')},
   next:()=>say(T,t(`你笑着说德州人什么都要做大。他被你逗乐了，一口气说了很多：每周二十车，先堆着，等“匝道批下来”。你记下了每一个字。可你走的时候，他在后视镜里多看了你一眼。`,`You laugh that Texans have to supersize everything. He's tickled and spills a lot at once: twenty loads a week, stockpiled, waiting "till the ramp gets approved." You remember every word. But as you leave, he gives you one more look in the side mirror.`,`Ris-te e dizes que os texanos têm de fazer tudo em ponto grande. Ele acha graça e conta muita coisa de uma vez: vinte cargas por semana, empilhadas, à espera «que aprovem a rampa». Guardas cada palavra. Mas quando te vais embora, ele olha-te mais uma vez pelo espelho.`),t(`好感 +1 · 你知道了“匝道”`,`Liking +1 · You've heard about "the ramp"`,`Afeição +1 · Ouviste falar da «rampa»`))}]);
 if(s===2)return sc(T,C.permian,[
  t(`敖德萨城外，路边那只巨大的长耳大野兔雕像下面，杰西把一个牛皮纸袋放在你的引擎盖上。里面是一沓货单的复印件：发货人“孤星砂业”，收货地“圣鲁伊斯中转站（筹建中）——罐头厂路”。最早的一张，日期比镇议会讨论罐头厂改划还早半年。`,`Outside Odessa, under the giant jackrabbit statue by the road, Jesse lays a manila envelope on your hood. Inside: copies of bills of lading. Shipper: Lone Star Sand LLC. Consignee: San Luís Transload (under construction) — Packing Co. Road. The earliest is dated half a year before the town council ever discussed rezoning the cannery.`,`À saída de Odessa, debaixo da enorme estátua de lebre à beira da estrada, o Jesse pousa um envelope pardo no capô. Lá dentro, cópias de guias de transporte. Expedidor: Lone Star Sand LLC. Destinatário: Terminal de San Luís (em construção) — Packing Co. Road. A mais antiga tem data de meio ano antes de a câmara alguma vez discutir a requalificação da fábrica.`),
  t(`“他们早就开始堆砂了，”杰西说，“好像那块地已经是他们的。”他又点了根烟，手有点抖，“我需要这份工作。我妈的心脏药、我妹妹上社区大学，全靠这辆车。”`,`"They've been stockpiling a long while," Jesse says, "like that land's already theirs." He lights another cigarette; his hand shakes a little. "I need this job. My mom's heart pills, my sister's community college — it all rides on this truck."`,`«Andam a acumular areia há muito tempo», diz o Jesse, «como se o terreno já fosse deles.» Acende outro cigarro; a mão treme-lhe um pouco. «Preciso deste trabalho. Os comprimidos do coração da minha mãe, a escola da minha irmã — tudo depende deste camião.»`)],[
  {t:t(`收下复印件，答应绝不说出他的名字`,`Take the copies and promise never to use his name`,`Aceitar as cópias e prometer nunca dizer o nome dele`),fx:()=>{S.flags.tx8_sand=1;addTrust('jesse',2);ADV('jesse','permian');log('杰西给了你孤星砂业的货单复印件','Jesse gave you copies of Lone Star Sand\'s bills of lading','O Jesse deu-te cópias das guias da Lone Star Sand')},
   next:()=>say(T,[t(`他点点头，把纸袋推给你，像把一块烫手的铁推开。“要是有人问，就说是风吹来的。”`,`He nods and pushes the envelope at you like a hot piece of iron. "Anybody asks, say the wind blew it in."`,`Acena e empurra o envelope para ti como quem afasta um ferro em brasa. «Se alguém perguntar, foi o vento que o trouxe.»`),S.flags.evidence?t(`你想起铁柜里若泽的水质报告。一个是过去，一个是现在：特拉维斯一直知道他想要那块地干什么。`,`You think of José's water report from the iron locker. One is the past, this is the present: Travis has always known exactly what he wanted that land for.`,`Pensas no relatório da água do José, do cacifo de ferro. Um é o passado, isto é o presente: o Travis sempre soube para que queria aquele terreno.`):t(`你还没有若泽留下的东西，但这些纸能说明：特拉维斯早就打算好了。`,`You don't have what José left behind yet, but these pages show Travis planned it all long ago.`,`Ainda não tens o que o José deixou, mas estes papéis mostram que o Travis planeou tudo há muito.`)],t(`得到：孤星砂业的货单（旁证）`,`Received: Lone Star Sand's bills of lading (side evidence)`,`Recebeste: as guias da Lone Star Sand (prova indireta)`))},
  {t:t(`把纸袋推回去：“你妈的药比我的地重要。”`,`Push the envelope back: "Your mom's pills matter more than my land."`,`Devolver o envelope: «Os comprimidos da tua mãe valem mais do que o meu terreno.»`),fx:()=>{addLike('jesse',3);addTrust('jesse',1);stat('charme',2);ADV('jesse','permian')},
   next:()=>say(T,t(`杰西愣住了。“在这片盆地，从来没人跟我说过这种话。”他没有收回纸袋，只是把它塞进了驾驶座底下，“那我先留着。等你需要的时候，它还在。”`,`Jesse stares. "Nobody out here's ever said a thing like that to me." He doesn't take the envelope back to the dispatcher; he tucks it under the driver's seat. "Then I'll hang on to it. When you need it, it'll be here."`,`O Jesse fica a olhar. «Nunca ninguém nesta bacia me disse uma coisa destas.» Não devolve o envelope; enfia-o debaixo do banco do condutor. «Então guardo-o eu. Quando precisares, está aqui.»`),t(`杰西好感 +3 · 魅力 +2`,`Jesse liking +3 · Charm +2`,`Afeição do Jesse +3 · Charme +2`))}]);
 if(s===3){const had=!!S.flags.tx8_sand;return sc(T,C.permian,[
  t(`这次杰西不在车里。你在敖德萨一家二十四小时洗衣店找到他，坐在塑料椅上看着自己的工装转圈。“调度把我叫去了，”他说，“问我有没有把货单给过别人。有个开新皮卡、戴银扣皮带的人在门口站着，一句话没说。”`,`This time Jesse isn't in his rig. You find him at a twenty-four-hour laundromat in Odessa, on a plastic chair, watching his work clothes go round. "Dispatch called me in," he says. "Asked if I'd shown the paperwork to anybody. Some man with a new pickup and a silver belt buckle stood in the doorway the whole time and never said a word."`,`Desta vez o Jesse não está no camião. Encontras-o numa lavandaria aberta vinte e quatro horas em Odessa, numa cadeira de plástico, a ver a roupa de trabalho às voltas. «O despacho chamou-me», diz. «Perguntaram se eu tinha mostrado os papéis a alguém. Um tipo de carrinha nova e fivela prateada ficou à porta o tempo todo sem dizer uma palavra.»`),
  t(`“我没说。”他看着你，“可我也不想再拉那种砂了。你说，我该怎么办？”`,`"I didn't tell." He looks at you. "But I don't wanna haul that sand anymore either. So what do I do?"`,`«Não disse nada.» Olha para ti. «Mas também já não quero levar aquela areia. Diz-me, o que é que eu faço?»`)],[
  {t:t(`帮他找一份跑冷藏车的活，从此给你的店带货`,`Help him find a refrigerated-freight job — and haul for your shop on the side`,`Ajudá-lo a arranjar trabalho num camião frigorífico — e trazer carga para o teu restaurante`),req:()=>S.rep>=20||rel('jesse').trust>=5||NEED(t(`口碑 20 或杰西信任 5`,`Reputation 20 or Jesse's trust 5`,`Reputação 20 ou confiança do Jesse 5`)),fx:()=>{addTrust('jesse',2);addLike('jesse',2);ADV('jesse','permian');grantPerk('pork',0.85,['杰西','Jesse','Jesse']);log('杰西改跑冷藏车，回程顺路给你带猪肉','Jesse switched to reefer freight and backhauls pork for you','O Jesse passou para frigoríficos e traz-te porco na volta')},
   next:()=>say(T,[t(`你打了三个电话：一个在你店里吃过饭的卡车司机，一个牧场的屠宰场，一个格蕾丝介绍的运输公司。一个星期后，杰西发来一张照片：一辆白色的冷藏半挂车，车门上贴着他妹妹画的星星。“回程空车，顺路给你拉猪肉。按油钱算。”`,`You make three calls: a trucker who eats at your shop, a ranch packing house, a freight company Grace knows. A week later Jesse texts a photo: a white refrigerated trailer, a star his sister painted on the door. "Coming back empty anyway — I'll bring your pork. Just gas money."`,`Fazes três chamadas: um camionista que come no teu restaurante, um matadouro de um rancho, uma transportadora que a Grace conhece. Uma semana depois o Jesse manda uma fotografia: um semirreboque frigorífico branco, com uma estrela pintada pela irmã na porta. «Na volta venho vazio — trago-te o porco. Só a gasolina.»`),...(had?[]:[t(`照片下面还有一行：“驾驶座底下那个纸袋，我寄给你了。”`,`Under the photo, one more line: "That envelope from under the seat — I mailed it to you."`,`Por baixo da fotografia, mais uma linha: «O envelope de debaixo do banco — mandei-to pelo correio.»`)])],t(`长期供货：猪肉 ×0.85 · 杰西信任 +2`,`Supply deal: pork ×0.85 · Jesse trust +2`,`Acordo: porco ×0.85 · Confiança do Jesse +2`))},
  {t:t(`请他到镇议会上，亲口说出他拉过什么、为谁拉`,`Ask him to tell the town council himself what he hauled and for whom`,`Pedir-lhe que diga ele próprio à câmara o que levou e para quem`),req:()=>rel('jesse').trust>=6||NEED(t(`杰西信任 6`,`Jesse's trust 6`,`Confiança do Jesse 6`)),fx:()=>{S.flags.tx8_sand=1;S.flags.tx8_jesseWitness=1;addTrust('jesse',1);stat('tex',2);ADV('jesse','permian');if(MET('colleen'))addTrust('colleen',1);log('杰西答应出面作证','Jesse agreed to testify','O Jesse aceitou testemunhar')},
   next:()=>say(T,[t(`他把烟掐了，过了很久才说：“我爸在油井上干了三十年，从来不敢跟老板说个‘不’字。”他站起来，把洗好的工装叠得整整齐齐，“告诉我日子。我开车过去。”`,`He stubs out the cigarette and is quiet a long time. "My dad worked the rigs thirty years and never once dared tell a boss no." He stands and folds his clean work clothes very neatly. "Tell me the date. I'll drive over."`,`Apaga o cigarro e fica muito tempo calado. «O meu pai trabalhou trinta anos nas sondas e nunca se atreveu a dizer que não a um patrão.» Levanta-se e dobra a roupa lavada com todo o cuidado. «Diz-me o dia. Eu vou lá.»`),...(MET('colleen')?[t(`你给科琳发了条短信。她只回了两个字：“好人。”`,`You text Colleen. She writes back two words: "Good man."`,`Mandas uma mensagem à Colleen. Ela responde só: «Bom homem.»`)]:[])],t(`杰西会作证 · 得到货单（旁证）`,`Jesse will testify · Bills of lading secured`,`O Jesse vai testemunhar · Guias garantidas`))},
  {t:t(`塞给他 $150：先把这个月熬过去`,`Slip him $150: get through this month first`,`Dar-lhe $150: primeiro aguentar este mês`),req:MONEY(150),fx:()=>{S.cash-=150;S.wk.spend+=150;addLike('jesse',3);S.rep+=2;ADV('jesse','permian')},
   next:()=>say(T,t(`他不肯收，你就把钱塞进他洗衣机的投币口旁边。后来，敖德萨好几个油田工人路过圣鲁伊斯时都进了你的店。“杰西说的，”他们说，“这是那个葡萄牙好人的店。”`,`He won't take it, so you leave it by the coin slot of his washer. Later, more than one Odessa roughneck passing through San Luís stops at your shop. "Jesse said," they tell you. "This is the good Portuguese fella's place."`,`Ele não aceita, por isso deixas o dinheiro junto à ranhura das moedas da máquina dele. Mais tarde, vários petroleiros de Odessa de passagem por San Luís param no teu restaurante. «Foi o Jesse que disse», contam. «Isto é a casa do português porreiro.»`),t(`−$150 · 杰西好感 +3 · 口碑 +2`,`−$150 · Jesse liking +3 · Reputation +2`,`−$150 · Afeição do Jesse +3 · Reputação +2`))},
  {t:t(`“让我想想。下次来再说。”`,`"Let me think on it. We'll talk next time."`,`«Deixa-me pensar. Falamos da próxima vez.»`),fx:()=>{S.flags.tx8_jesse_v=VIS('permian');addTrust('jesse',0.5)}}])}
 return sc(T,C.permian,[P3([`杰西的车停在停车场最边上，车门上那颗星星又补过漆了。他扔给你一罐冰汽水：“今天风大，别站在砂车后面。”`,`杰西在敖德萨的高中球场外面等你，说他妹妹考试拿了全班第一。`,`杰西靠在车头上吃你带的烤肠，说盆地的风“能把人的名字都吹走”。`],[`Jesse's rig is parked at the far end of the lot; the star on the door has been touched up. He tosses you a cold soda. "Windy today. Don't stand downwind of a sand truck."`,`Jesse waits for you outside the Odessa high-school stadium, saying his sister came top of her class.`,`Jesse leans on his hood eating the sausage you brought, saying the Basin wind "can blow the name right off a man."`],[`O camião do Jesse está no fim do parque; a estrela na porta foi retocada. Atira-te um refrigerante gelado. «Hoje há vento. Não fiques atrás de um camião de areia.»`,`O Jesse espera-te à porta do estádio do liceu de Odessa e conta que a irmã ficou em primeiro lugar da turma.`,`O Jesse, encostado ao capô, come o chouriço que trouxeste e diz que o vento da Bacia «até leva o nome a um homem».`])],[
  {t:t(`聊一会儿`,`Talk a while`,`Conversar um bocado`),fx:()=>{stamp('jesse');addLike('jesse',1);stat('tex',1)}}]);
}

/* ---------------- WALT (San Angelo) ---------------- */
function waltScene(){const s=ST('waltk'),T=t(`羊毛仓库`,`The wool warehouse`,`O armazém da lã`);
 if(s===0)return sc(T,C.sanangelo,[
  t(`康乔河边的老仓库区，砖墙上还看得见褪色的大字：“羊毛与马海毛”。屋里堆着一人高的麻布包，空气里是羊脂和灰尘的味道。一个穿背带裤的老人把手伸进一包羊毛里，闭着眼睛，像在听什么。`,`The old warehouse district by the Concho River; on the brick you can still read the faded letters: WOOL & MOHAIR. Inside, burlap bales are stacked head high and the air smells of lanolin and dust. An old man in overalls has his hand buried in a fleece, eyes closed, as if listening for something.`,`O velho bairro dos armazéns junto ao rio Concho; nos tijolos ainda se leem as letras desbotadas: LÃ E MOHAIR. Lá dentro, fardos de serapilheira empilhados à altura de um homem, e o ar cheira a lanolina e pó. Um velho de jardineiras tem a mão enterrada num velo, de olhos fechados, como se estivesse a escutar.`),
  t(`“二十一微米，”他睁开眼，“好羊。”他打量你：“西班牙人？”你说葡萄牙人。他咧嘴笑了：“那差不多是亲戚。美利奴羊最早就是从你们那半岛来的。我叫沃尔特，这一行干了五十二年。人们常说这座城以前是全国最大的羊毛市场。现在嘛——”他拍拍麻布包，“现在就剩我和这些包了。”`,`"Twenty-one micron," he says, opening his eyes. "Good sheep." He looks you over. "Spaniard?" You say Portuguese. He grins. "Near enough kin. The merino came from your peninsula first. Name's Walt. Fifty-two years in this trade. Folks say this town was once the biggest wool market in the country. Now —" he pats a bale, "now it's me and these bags."`,`«Vinte e um mícrones», diz, abrindo os olhos. «Boa ovelha.» Mede-te de alto a baixo. «Espanhol?» Dizes que és português. Ele sorri. «Quase família. A merina veio primeiro da vossa península. Chamo-me Walt. Cinquenta e dois anos neste negócio. Diz-se que esta cidade já foi o maior mercado de lã do país. Agora —» dá uma palmada num fardo, «agora sou eu e estes sacos.»`)],[
  {t:t(`请他教你用手摸羊毛分级`,`Ask him to teach you to grade wool by hand`,`Pedir-lhe que te ensine a classificar a lã à mão`),fx:()=>{rel('waltk').met=true;addLike('waltk',2);stat('oficio',2);stat('tex',1);ADV('waltk','sanangelo');log('在圣安吉洛认识了羊毛商沃尔特','Met Walt the wool buyer in San Angelo','Conheceste o Walt, comprador de lã, em San Angelo')},
   next:()=>say(T,t(`你摸错了三次，第四次说对了。沃尔特点点头：“手比眼睛诚实。挑肉也一样吧？”你说一样。他从口袋里掏出一张名片，上面印着一只羊：“下次来，我请你吃我老伴的拿手菜。她走了六年，菜谱还在。”`,`You guess wrong three times and right the fourth. Walt nods. "Hands are honester than eyes. Same with picking meat, I'd reckon?" You say it's the same. He pulls a card from his pocket with a sheep printed on it. "Next time, I'll feed you my wife's best dish. She's been gone six years. The recipe's still here."`,`Erras três vezes e acertas à quarta. O Walt acena. «As mãos são mais honestas do que os olhos. Com a carne é igual, não?» Dizes que sim. Tira do bolso um cartão com uma ovelha impressa. «Da próxima vez dou-te a comer o melhor prato da minha mulher. Morreu há seis anos. A receita ficou.»`),t(`认识了沃尔特 · 手艺 +2 · 德州味 +1`,`Met Walt · Craft +2 · Texanness +1`,`Conheceste o Walt · Ofício +2 · Texanidade +1`))},
  {t:t(`跟他开玩笑：葡萄牙的羊比较会唱歌`,`Joke that Portuguese sheep sing better`,`Brincar que as ovelhas portuguesas cantam melhor`),fx:()=>{rel('waltk').met=true;addLike('waltk',3);stat('charme',1);ADV('waltk','sanangelo');log('在圣安吉洛认识了羊毛商沃尔特','Met Walt the wool buyer in San Angelo','Conheceste o Walt, comprador de lã, em San Angelo')},
   next:()=>say(T,t(`沃尔特笑得咳嗽起来，扶着麻布包才站稳。“我老伴要是在，会喜欢你的。她就喜欢嘴贫的。”他擦擦眼睛，“下次来，我做她的菜给你吃。”`,`Walt laughs till he coughs and has to steady himself on a bale. "My wife would've liked you. She always did go for the smart-mouthed ones." He wipes his eyes. "Next time, I'll cook you her dish."`,`O Walt ri-se até tossir e tem de se apoiar num fardo. «A minha mulher ia gostar de ti. Sempre teve um fraco pelos espertalhões.» Limpa os olhos. «Da próxima vez cozinho-te o prato dela.»`),t(`认识了沃尔特 · 好感 +3`,`Met Walt · Liking +3`,`Conheceste o Walt · Afeição +3`))}]);
 if(s===1)return sc(T,C.sanangelo,[
  t(`沃尔特家的厨房在仓库后面，墙上挂着一张黑白照片：一个戴宽檐帽的女人站在剪羊毛棚前，笑得很大声的样子。他把一块牛排用木槌敲薄，裹面粉、蘸蛋奶、再裹面粉，放进铁锅里的热油。“贝蒂说，秘诀是第二遍面粉要按实，还有锅里的肉汁不能浪费。”`,`Walt's kitchen is behind the warehouse. On the wall, a black-and-white photo: a woman in a wide-brimmed hat in front of a shearing shed, laughing out loud by the look of it. He pounds a steak thin with a wooden mallet, dredges it in flour, then egg and milk, then flour again, and lays it into hot oil in a cast-iron skillet. "Betty said the secret's pressing that second coat of flour on hard. And never waste the pan drippings."`,`A cozinha do Walt fica atrás do armazém. Na parede, uma fotografia a preto e branco: uma mulher de chapéu de aba larga em frente a um barracão de tosquia, a rir às gargalhadas, pelo ar dela. Ele bate um bife até ficar fino com um maço de madeira, passa-o por farinha, depois ovo e leite, depois farinha outra vez, e deita-o no óleo quente de uma frigideira de ferro. «A Betty dizia que o segredo é carregar bem na segunda camada de farinha. E nunca desperdiçar o molho do fundo da frigideira.»`),
  t(`他用锅底的油和面粉做了白色的胡椒肉汁，浇在炸牛排上。“西德州人一半是这道菜喂大的。”`,`From the drippings and flour he makes a white peppered gravy and pours it over the steak. "Half of West Texas was raised on this."`,`Com a gordura do fundo e farinha faz um molho branco de pimenta e deita-o por cima do bife. «Metade do Oeste do Texas foi criada com isto.»`)],[
  {t:t(`认真学：这道菜你要带回店里`,`Study it properly — this one's going on your menu`,`Aprender a sério — isto vai para a tua ementa`),fx:()=>{learnDish('tx8_betty');addTrust('waltk',2);stat('oficio',2);ADV('waltk','sanangelo')},
   next:()=>say(T,[t(`你炸的第二块终于没有脱皮。沃尔特尝了一口，对着墙上的照片说：“贝蒂，这小子行。”`,`Your second steak finally keeps its crust. Walt takes a bite and says to the photo on the wall, "Betty, the boy's all right."`,`O teu segundo bife finalmente não perde a crosta. O Walt prova e diz para a fotografia na parede: «Betty, o rapaz tem jeito.»`),...(MET('earl')?[t(`你说起圣鲁伊斯的厄尔。沃尔特放下叉子：“厄尔·惠特莫尔？那个在牛仔竞技上摔断过三根肋骨的疯子？他还活着？替我告诉他，他还欠我一顶帽子。”`,`You mention Earl back in San Luís. Walt sets down his fork. "Earl Whitmore? The fool who broke three ribs at the rodeo? He's still kicking? You tell him he still owes me a hat."`,`Falas do Earl, lá de San Luís. O Walt pousa o garfo. «Earl Whitmore? O maluco que partiu três costelas no rodeo? Ainda está vivo? Diz-lhe que ainda me deve um chapéu.»`)]:[])],t(`学会：乡村炸牛排 · 沃尔特信任 +2`,`Learned: chicken-fried steak · Walt trust +2`,`Aprendeste: bife panado à texana · Confiança do Walt +2`))},
  {t:t(`问他贝蒂的事`,`Ask him about Betty`,`Perguntar-lhe pela Betty`),fx:()=>{learnDish('tx8_betty');addLike('waltk',2);addTrust('waltk',1);stat('saud',-3);ADV('waltk','sanangelo')},
   next:()=>say(T,t(`“她在剪毛棚给四十个剪毛工做饭，一干三十年。”他慢慢地说，“剪毛工是从墨西哥、从新西兰来的，一个镇一个镇地剪过去。贝蒂说，人离家远了，就得有一口热的。”他把菜谱卡片抄了一份给你。你想起阿尔法马的外婆，心里那块地方暖了一下。`,`"She cooked for forty shearers in the shearing shed for thirty years," he says slowly. "Shearers came up from Mexico, from New Zealand, working town to town. Betty said a man far from home needs something hot." He copies the recipe card for you. You think of your grandmother in Alfama, and something in your chest warms.`,`«Cozinhou trinta anos para quarenta tosquiadores no barracão», diz devagar. «Os tosquiadores vinham do México, da Nova Zelândia, de terra em terra. A Betty dizia que um homem longe de casa precisa de uma coisa quente.» Copia-te o cartão da receita. Pensas na tua avó em Alfama, e qualquer coisa no peito aquece.`),t(`学会：乡村炸牛排 · 乡愁 −3`,`Learned: chicken-fried steak · Homesickness −3`,`Aprendeste: bife panado à texana · Saudade −3`))}]);
 if(s===2)return sc(T,C.sanangelo,[
  t(`仓库里的麻布包少了一半。沃尔特坐在磅秤上，手里捏着一封信。“我孙子在休斯敦，搞电脑的。他说爷爷你七十七了，把仓库卖了吧。有人出价，要改成公寓。”他看着空出来的地板，“羊毛这一行，年轻人不干了。你说我是不是该卖？”`,`Half the bales are gone. Walt sits on the scale holding a letter. "My grandson's in Houston, does computers. Says Grandpa, you're seventy-seven, sell the warehouse. Somebody's made an offer — wants to turn it into apartments." He looks at the empty floor. "Young folks don't go into wool anymore. You think I ought to sell?"`,`Metade dos fardos desapareceu. O Walt está sentado na balança com uma carta na mão. «O meu neto está em Houston, trabalha com computadores. Diz: avô, tens setenta e sete anos, vende o armazém. Alguém fez uma oferta — quer fazer apartamentos.» Olha para o chão vazio. «Os novos já não querem a lã. Achas que devia vender?»`),
  ...(inSeason(33,36)?[t(`窗外，牲畜展的彩旗挂满了整条街，卡车拉着一车车山羊和绵羊往展馆开。这是他一年里最忙的时候，可他今年一次都没去。`,`Outside, stock-show bunting hangs the length of the street and trailers of goats and sheep roll toward the show barns. It's his busiest time of year, and this year he hasn't gone once.`,`Lá fora, as bandeirolas da feira de gado enchem a rua e passam atrelados de cabras e ovelhas a caminho dos pavilhões. É a altura mais ocupada do ano para ele, e este ano ainda lá não foi.`)]:[])],[
  {t:t(`说实话：你也继承了一个不想放手的地方`,`Tell the truth: you inherited a place you won't let go of either`,`Dizer a verdade: também herdaste um sítio que não queres largar`),fx:()=>{addTrust('waltk',3);stat('saud',2);ADV('waltk','sanangelo')},
   next:()=>say(T,[t(`你讲了若泽，讲了店后那块空地，讲了有人一直想买它。沃尔特听完，很久没说话。“我不卖给开发商，”他终于说，“我卖给剪毛工的合作社。价钱低一点，可这里还是羊毛的地方。”`,`You tell him about José, about the lot behind the shop, about the man who keeps trying to buy it. Walt is quiet a long while after. "I won't sell to the developer," he says at last. "I'll sell to the shearers' co-op. Less money. But it stays a wool place."`,`Falas-lhe do José, do terreno atrás do restaurante, do homem que não para de o querer comprar. O Walt fica muito tempo calado. «Não vendo ao promotor», diz por fim. «Vendo à cooperativa dos tosquiadores. Menos dinheiro. Mas continua a ser um sítio de lã.»`),...(MET('travis')?[t(`“那个想买你地的人，”他补了一句，“不管他姓什么，你别卖。”`,`"That fella who wants your land," he adds, "whatever his name is — don't sell."`,`«Esse tipo que te quer o terreno», acrescenta, «seja qual for o nome dele — não vendas.»`)]:[])],t(`沃尔特信任 +3`,`Walt trust +3`,`Confiança do Walt +3`))},
  {t:t(`劝他卖：七十七岁了，去休斯敦看孙子`,`Tell him to sell: at seventy-seven, go see the grandkids in Houston`,`Dizer-lhe que venda: aos setenta e sete, ir ver os netos a Houston`),fx:()=>{addLike('waltk',1);stat('tex',1);ADV('waltk','sanangelo')},
   next:()=>say(T,t(`沃尔特点点头，又摇摇头。“你说得对。可是休斯敦的空气里没有羊毛味。”他把信折起来塞进胸口的口袋，“我再想想。”`,`Walt nods, then shakes his head. "You're right. But Houston air don't smell like wool." He folds the letter into his chest pocket. "I'll think on it."`,`O Walt acena, depois abana a cabeça. «Tens razão. Mas o ar de Houston não cheira a lã.» Dobra a carta e mete-a no bolso do peito. «Vou pensar.»`),t(`沃尔特好感 +1`,`Walt liking +1`,`Afeição do Walt +1`))}]);
 if(s===3)return sc(T,C.sanangelo,[
  t(`最后一批羊毛装车那天，沃尔特穿了一件熨过的衬衫。剪毛工、牧场主、几位戴宽檐帽的老太太都来了，站在仓库门口喝咖啡。卡车开走以后，沃尔特把一条叠好的毯子递给你：马海毛的，摸起来像云。“贝蒂织的，一共三条。这一条给你。”`,`The day the last wool loads out, Walt wears an ironed shirt. Shearers, ranchers and a few old ladies in wide-brimmed hats have come, drinking coffee at the warehouse door. When the truck pulls away, Walt hands you a folded blanket: mohair, soft as a cloud. "Betty wove three. This one's yours."`,`No dia em que sai a última carga de lã, o Walt veste uma camisa passada a ferro. Vieram tosquiadores, rancheiros e umas senhoras de chapéu de aba larga, a beber café à porta do armazém. Quando o camião arranca, o Walt dá-te uma manta dobrada: mohair, macia como uma nuvem. «A Betty teceu três. Esta é tua.»`),
  t(`一位老太太走过来：“我们几家牧场的女人合办了一个小合作社：鸡蛋、黄油、自己磨的面粉。沃尔特说你的面包做得不错。要不要按合作社的价钱给你送货？”`,`One of the old ladies comes over. "A few of us ranch women run a little co-op — eggs, butter, flour we mill ourselves. Walt says your bread's not bad. Want us to ship to you at co-op prices?"`,`Uma das senhoras aproxima-se. «Umas quantas mulheres de rancho temos uma pequena cooperativa — ovos, manteiga, farinha moída por nós. O Walt diz que o teu pão não é mau. Queres que te mandemos a preço de cooperativa?»`)],[
  {t:t(`收下毯子，和合作社握手成交`,`Take the blanket and shake on the co-op deal`,`Aceitar a manta e fechar negócio com a cooperativa`),fx:()=>{S.flags.tx8_waltBlanket=1;addTrust('waltk',2);addLike('waltk',2);stat('saud',-4);ADV('waltk','sanangelo');grantPerk('dairy',0.8,['康乔河牧场合作社','Concho ranch-women\'s co-op','Cooperativa das rancheiras do Concho']);if(MET('earl'))addLike('earl',1);log('沃尔特送你一条马海毛毯子；康乔河合作社长期供货','Walt gave you a mohair blanket; the Concho co-op will supply you','O Walt deu-te uma manta de mohair; a cooperativa do Concho vai fornecer-te')},
   next:()=>say(T,[t(`那天晚上你把毯子铺在楼上的床上。冬天的风从门缝钻进来，被毯子挡在外面。`,`That night you spread the blanket on your bed upstairs. The winter wind slips through the door cracks and stops at the blanket.`,`Nessa noite estendes a manta na tua cama lá em cima. O vento de inverno entra pelas frinchas da porta e para na manta.`),...(MET('earl')?[t(`回去以后，你把沃尔特的话带给厄尔。厄尔骂了一句，转身从柜子里翻出一顶旧帽子，让你下次带去。`,`Back home, you pass Walt's message to Earl. Earl swears, then digs an old hat out of a cupboard and tells you to take it next time.`,`Em casa, dás o recado do Walt ao Earl. O Earl pragueja, depois tira um chapéu velho de um armário e diz-te para o levares da próxima vez.`)]:[])],t(`长期供货：面粉蛋奶 ×0.8 · 乡愁 −4`,`Supply deal: flour, eggs & milk ×0.8 · Homesickness −4`,`Acordo: farinha, ovos e leite ×0.8 · Saudade −4`))},
  {t:t(`把毯子还给他：“这是贝蒂的，你留着。”`,`Give the blanket back: "It's Betty's. Keep it."`,`Devolver a manta: «É da Betty. Fica com ela.»`),fx:()=>{addTrust('waltk',3);addLike('waltk',2);stat('charme',2);ADV('waltk','sanangelo');grantPerk('dairy',0.8,['康乔河牧场合作社','Concho ranch-women\'s co-op','Cooperativa das rancheiras do Concho'])},
   next:()=>say(T,t(`沃尔特把毯子抱在怀里，像抱一只小羊。老太太们互相看了一眼，其中一位拍拍你的胳膊：“合作社的事照样算数。这样的小伙子，我们不赚他的钱。”`,`Walt holds the blanket to his chest like a lamb. The old ladies exchange a look, and one pats your arm. "The co-op deal stands all the same. Boy like that, we won't make money off him."`,`O Walt aperta a manta ao peito como um cordeiro. As senhoras trocam um olhar e uma dá-te uma palmadinha no braço. «O acordo da cooperativa mantém-se. Com um rapaz destes não queremos lucro.»`),t(`长期供货：面粉蛋奶 ×0.8 · 沃尔特信任 +3`,`Supply deal: flour, eggs & milk ×0.8 · Walt trust +3`,`Acordo: farinha, ovos e leite ×0.8 · Confiança do Walt +3`))}]);
 return sc(T,C.sanangelo,[P3([`沃尔特现在每天上午去剪毛工合作社“监工”，其实就是喝咖啡、挑别人的毛病。`,`沃尔特带你在河边看那些涂得花花绿绿的羊雕像，一只一只地说是谁画的。`,`沃尔特说他孙子从休斯敦来过了，学会了用手摸羊毛分级。“十九微米，他说对了。”`],[`Walt now goes to the shearers' co-op every morning to "supervise" — which means drinking coffee and finding fault.`,`Walt walks you along the river past the painted sheep statues, telling you who painted each one.`,`Walt says his grandson came out from Houston and learned to grade wool by hand. "Nineteen micron. He got it right."`],[`O Walt vai agora todas as manhãs à cooperativa dos tosquiadores «supervisionar» — ou seja, beber café e pôr defeitos.`,`O Walt leva-te pela margem do rio a ver as estátuas de ovelhas pintadas e diz-te quem pintou cada uma.`,`O Walt conta que o neto veio de Houston e aprendeu a classificar lã à mão. «Dezanove mícrones. Acertou.»`])],[
  {t:t(`陪他坐一会儿`,`Sit with him a while`,`Ficar um bocado com ele`),fx:()=>{stamp('waltk');addLike('waltk',1);stat('saud',-1)}}]);
}
/* ---------------- ADA (Abilene) ---------------- */
function adaScene(){const s=ST('ada'),T=t(`插画家`,`The illustrator`,`A ilustradora`);
 if(s===0)return sc(T,C.abilene,[
  t(`阿比林市中心的人行道上，到处是童书里的人物：铜做的小兔子、戴帽子的猫、一条从书里爬出来的龙。人们常说这里是“全美童书之都”。一个女人盘腿坐在一只铜熊旁边，膝盖上摊着速写本，铅笔飞快——她画的不是熊，是你。`,`All over the sidewalks of downtown Abilene stand characters from children's books: a bronze rabbit, a cat in a hat, a dragon crawling out of a book. People call it the Storybook Capital of America. A woman sits cross-legged beside a bronze bear with a sketchbook on her knees, pencil flying — and she isn't drawing the bear. She's drawing you.`,`Pelos passeios do centro de Abilene há personagens de livros infantis por todo o lado: um coelho de bronze, um gato de chapéu, um dragão a sair de um livro. Chamam-lhe a Capital do Livro Infantil da América. Uma mulher sentada de pernas cruzadas ao lado de um urso de bronze tem um caderno nos joelhos e o lápis a voar — e não está a desenhar o urso. Está a desenhar-te a ti.`),
  t(`“抱歉！”她举起本子，“你站着看那只兔子的样子，像个迷路的王子。我叫艾达，画童书的。”画上的你确实很好看，也确实很迷茫。`,`"Sorry!" She holds up the page. "The way you were standing there looking at that rabbit — like a lost prince. I'm Ada. I draw children's books." The you on the page is very handsome, and very lost.`,`«Desculpa!» Levanta a folha. «A maneira como estavas ali a olhar para aquele coelho — parecias um príncipe perdido. Sou a Ada. Faço ilustração de livros infantis.» O tu do desenho é muito bonito, e está muito perdido.`)],[
  {t:t(`${faceWord()}摆个姿势，让她画完`,`${faceWord()}strike a pose and let her finish`,`${faceWord()}fazer pose e deixá-la acabar`),req:CHARM_REQ(40),fx:()=>{flirt();rel('ada').met=true;addLike('ada',2);stat('charme',2);ADV('ada','abilene');log('在阿比林认识了插画家艾达','Met Ada, an illustrator, in Abilene','Conheceste a Ada, ilustradora, em Abilene')},
   next:()=>say(T,t(`她画完了，撕下来送给你，又马上说：“可是王子太无聊了。小孩子不喜欢王子，喜欢有故事的人。”她在本子边上写了个电话，“下次来，给我讲个故事。”`,`She finishes, tears out the page and hands it to you — then says at once, "But princes are boring. Kids don't like princes. They like people with stories." She writes a number in the margin. "Next time, tell me one."`,`Acaba, arranca a folha e dá-ta — e diz logo: «Mas os príncipes são aborrecidos. Os miúdos não gostam de príncipes. Gostam de pessoas com histórias.» Escreve um número na margem. «Da próxima vez conta-me uma.»`),t(`认识了艾达 · 魅力 +2`,`Met Ada · Charm +2`,`Conheceste a Ada · Charme +2`))},
  {t:t(`说实话：你不是王子，是个开烧烤店的`,`Tell the truth: you're no prince, you run a grill`,`Dizer a verdade: não és príncipe, tens uma churrasqueira`),fx:()=>{rel('ada').met=true;addLike('ada',1);addTrust('ada',2);ADV('ada','abilene');log('在阿比林认识了插画家艾达','Met Ada, an illustrator, in Abilene','Conheceste a Ada, ilustradora, em Abilene')},
   next:()=>say(T,[t(`她眼睛一亮：“里斯本来的烧烤师傅，在德州？这就是故事。”她把“王子”两个字划掉，在旁边画了一把夹子。`,`Her eyes light up. "A grill man from Lisbon, in Texas? Now that's a story." She crosses out the word PRINCE and draws a pair of tongs beside it.`,`Os olhos dela acendem-se. «Um churrasqueiro de Lisboa no Texas? Isso sim é uma história.» Risca a palavra PRÍNCIPE e desenha uma pinça ao lado.`),t(`“我爸是退休牧师，在这里的神学院读的书，”她说，“阿比林三所大学都是教会办的，人们常说这里教堂比加油站还多。”`,`"My dad's a retired preacher — went to seminary right here," she says. "All three universities in Abilene are church schools. Folks say there are more churches here than gas stations."`,`«O meu pai é pastor reformado — estudou teologia aqui mesmo», diz. «As três universidades de Abilene são de igrejas. Diz-se que há mais igrejas do que bombas de gasolina.»`)],t(`认识了艾达 · 信任 +2`,`Met Ada · Trust +2`,`Conheceste a Ada · Confiança +2`))}]);
 if(s===1)return sc(T,C.abilene,[
  t(`老火车站的红砖站房如今是游客中心，站台上已经很少有客车停了，货运列车还是每天轰隆隆地经过。艾达坐在月台长椅上，速写本上全是被划掉的草稿。“出版社要我画一本关于‘远方来的人’的书。我画了十二个开头，都是假的。”`,`The old red-brick railway depot is a visitor center now; passenger trains rarely stop, but freight trains still thunder through every day. Ada sits on a platform bench, her sketchbook full of crossed-out drafts. "My publisher wants a book about 'someone who came from far away.' I've drawn twelve openings. They're all fake."`,`A velha estação de tijolo vermelho é agora um centro de visitantes; os comboios de passageiros raramente param, mas os de mercadorias ainda passam a trovejar todos os dias. A Ada está num banco da plataforma, com o caderno cheio de rascunhos riscados. «A editora quer um livro sobre "alguém que veio de longe". Fiz doze começos. São todos falsos.»`),
  t(`“这座城是铁路造出来的，”她指着铁轨，“一百多年前火车来了，城就长出来了。那你呢？你是怎么来的？”`,`"This town was built by the railroad," she says, pointing at the tracks. "Train came through a hundred-some years ago and the town grew up around it. What about you? How'd you get here?"`,`«Esta cidade foi feita pelo caminho de ferro», diz, apontando os carris. «O comboio chegou há mais de cem anos e a cidade cresceu à volta. E tu? Como é que vieste parar aqui?»`)],[
  {t:t(`讲若泽：一个从海边走到德州、再也没回家的人`,`Tell her about José: a man who walked from the sea to Texas and never went home`,`Falar-lhe do José: um homem que saiu do mar para o Texas e nunca voltou a casa`),fx:()=>{addTrust('ada',2);addLike('ada',1);stat('saud',3);ADV('ada','abilene')},
   next:()=>say(T,t(`你讲了渔船、烤架、店后那块空地，还有那些没寄出去的信。艾达没有画画，只是听。最后她说：“那这本书不是关于你的。是关于一个人怎么替另一个人回家。”她翻开新的一页，画了一条船，船上有一个烤架。`,`You tell her about the boat, the grill, the lot behind the shop, the letters never mailed. Ada doesn't draw; she just listens. At last she says, "Then this book isn't about you. It's about how one person goes home for another." She turns to a fresh page and draws a boat with a grill on it.`,`Falas-lhe do barco, da grelha, do terreno atrás do restaurante, das cartas nunca enviadas. A Ada não desenha; só ouve. Por fim diz: «Então este livro não é sobre ti. É sobre como uma pessoa volta a casa por outra.» Vira para uma página nova e desenha um barco com uma grelha.`),t(`艾达信任 +2 · 乡愁 +3`,`Ada trust +2 · Homesickness +3`,`Confiança da Ada +2 · Saudade +3`))},
  {t:t(`讲你自己：坐灰狗巴士来，下车第一眼看见的是一个水塔`,`Tell her about yourself: arriving by Greyhound, a water tower the first thing you saw`,`Falar de ti: chegaste de Greyhound e a primeira coisa que viste foi uma torre de água`),fx:()=>{addLike('ada',2);stat('charme',1);stat('tex',1);ADV('ada','abilene')},
   next:()=>say(T,t(`艾达笑出声：“水塔！小孩子会喜欢水塔的。”她画了一个拖着行李箱的小人，站在一个巨大的水塔下面，抬头张着嘴。“下次来，我给你看草稿。”`,`Ada laughs. "A water tower! Kids'll love a water tower." She draws a tiny figure with a suitcase standing under an enormous water tower, mouth open, looking up. "Next time, I'll show you the drafts."`,`A Ada ri-se. «Uma torre de água! Os miúdos vão adorar uma torre de água.» Desenha um bonequinho com uma mala, debaixo de uma torre de água enorme, de boca aberta a olhar para cima. «Da próxima vez mostro-te os rascunhos.»`),t(`艾达好感 +2`,`Ada liking +2`,`Afeição da Ada +2`))}]);
 if(s===2)return sc(T,C.abilene,[
  t(`儿童插画文学中心楼上，艾达的草稿用夹子挂了一整面墙。一个男孩带着一条看不见的海，从里斯本坐船、坐火车、坐巴士来到德州一座有水塔的小镇。最后一页还是空白的。“我不知道结尾。”她说，“书里的那块空地，最后变成什么？”`,`Upstairs at the children's illustrated-literature center, Ada's drafts are clipped up across a whole wall. A boy carries an invisible sea from Lisbon by ship, by train, by bus to a little Texas town with a water tower. The last page is still blank. "I don't know the ending," she says. "The empty lot in the book — what does it become?"`,`No andar de cima do centro de literatura infantil ilustrada, os rascunhos da Ada estão presos por molas numa parede inteira. Um rapaz leva um mar invisível de Lisboa de barco, de comboio, de autocarro até uma vilazinha do Texas com uma torre de água. A última página continua em branco. «Não sei o fim», diz. «O terreno vazio do livro — em que é que se transforma?»`),
  ...(MET('dale')?[t(`她又递给你一个信封：“我爸让我转交给你们镇上的戴尔·金凯德牧师。他们四十年前是神学院的室友。”`,`She hands you an envelope too. "My dad asked me to pass this to Pastor Dale Kincaid in your town. They were seminary roommates forty years ago."`,`Dá-te também um envelope. «O meu pai pediu-me para entregar isto ao Pastor Dale Kincaid, da tua terra. Foram colegas de quarto no seminário há quarenta anos.»`)]:[])],[
  {t:t(`“一场节日。全镇的人在那里烤沙丁鱼。”`,`"A festival. The whole town grilling sardines there."`,`«Uma festa. A vila inteira a assar sardinhas ali.»`),fx:()=>{addTrust('ada',2);addLike('ada',1);ADV('ada','abilene');if(MET('dale'))addTrust('dale',1)},
   next:()=>say(T,t(`艾达画了一夜。早上她给你看最后一页：彩旗、罗勒小盆、长桌，桌边坐着牧场主、卡车司机、老太太和小孩，烟往天上飘，飘成一条船的形状。`,`Ada draws all night. In the morning she shows you the last page: garlands, little pots of basil, long tables, ranchers and truckers and old ladies and kids around them, smoke drifting up into the shape of a boat.`,`A Ada desenha a noite inteira. De manhã mostra-te a última página: grinaldas, vasinhos de manjerico, mesas compridas, rancheiros, camionistas, velhinhas e crianças à volta, e o fumo a subir com a forma de um barco.`),t(`艾达信任 +2`,`Ada trust +2`,`Confiança da Ada +2`))},
  {t:t(`“我还不知道。也许什么都不是。”`,`"I don't know yet. Maybe nothing."`,`«Ainda não sei. Talvez nada.»`),fx:()=>{addTrust('ada',3);stat('saud',2);ADV('ada','abilene');if(MET('dale'))addTrust('dale',1)},
   next:()=>say(T,t(`艾达看了你很久，然后把最后一页留成空白，只在角落里画了一个很小的问号。“那就让读书的小孩自己画。最诚实的结尾。”`,`Ada looks at you a long time, then leaves the last page blank, with only a tiny question mark in one corner. "Then the kids reading it can draw it themselves. Most honest ending there is."`,`A Ada olha para ti muito tempo e depois deixa a última página em branco, só com um pontinho de interrogação num canto. «Então os miúdos que o lerem desenham-no eles. É o fim mais honesto que há.»`),t(`艾达信任 +3 · 乡愁 +2`,`Ada trust +3 · Homesickness +2`,`Confiança da Ada +3 · Saudade +2`))}]);
 if(s===3)return sc(T,C.abilene,[
  t(`书印出来了，薄薄的一本，封面是一个男孩站在水塔下，手里提着一个装满海水的桶。艾达在第一页签了名：“给真正的那个男孩。”她说一家小出版社先印了两千本，西德州的几个图书馆都订了。`,`The book is printed: a thin one, the cover a boy under a water tower holding a bucket full of sea. Ada signs the first page: "For the real boy." A small press has run two thousand copies, she says, and several West Texas libraries have ordered it.`,`O livro saiu: fininho, com a capa de um rapaz debaixo de uma torre de água a segurar um balde cheio de mar. A Ada assina a primeira página: «Para o rapaz verdadeiro.» Diz que uma pequena editora imprimiu dois mil exemplares e várias bibliotecas do Oeste do Texas já encomendaram.`)],[
  {t:t(`请她来圣鲁伊斯，给镇上的小孩念这本书`,`Invite her to San Luís to read it to the town's kids`,`Convidá-la a ir a San Luís ler o livro às crianças da vila`),fx:()=>{S.flags.tx8_book=1;addLike('ada',2);addTrust('ada',1);S.rep+=4;ONL(5);ADV('ada','abilene');log('艾达的童书印出来了，她会来圣鲁伊斯朗读','Ada\'s picture book is out; she\'ll come to San Luís to read it','O livro da Ada saiu; ela vai a San Luís lê-lo')},
   next:()=>say(T,[t(`一个星期六下午，艾达坐在你店里的长凳上，身边围了二十几个小孩。汤米和小戴尔假装不感兴趣，站在门口偷听。念到最后一页，一个小女孩举手：“那块空地是真的吗？”所有人都看向店后面。`,`One Saturday afternoon Ada sits on a bench in your shop with twenty-some kids around her. Tommy and Little Dale pretend not to care and listen from the doorway. At the last page a little girl raises her hand: "Is the empty lot real?" Everyone turns to look behind the shop.`,`Num sábado à tarde a Ada senta-se num banco do teu restaurante com mais de vinte miúdos à volta. O Tommy e o pequeno Dale fingem que não querem saber e ouvem da porta. Na última página uma menina põe o dedo no ar: «O terreno vazio é a sério?» Toda a gente se vira para trás do restaurante.`),t(`那个星期，家长们带着孩子来吃饭的多了一倍。`,`That week, twice as many parents bring their kids in to eat.`,`Nessa semana, o dobro dos pais traz os filhos para comer.`)],t(`口碑 +4 · 线上评分 +5 · 艾达的书`,`Reputation +4 · Online +5 · Ada's book`,`Reputação +4 · Online +5 · O livro da Ada`))},
  {t:t(`买下五十本，放在店里送给来吃饭的家庭`,`Buy fifty copies to give away to families who eat at the shop`,`Comprar cinquenta exemplares para oferecer às famílias que comem no restaurante`),req:MONEY(200),fx:()=>{S.cash-=200;S.wk.spend+=200;S.flags.tx8_book=1;addLike('ada',3);S.rep+=3;ONL(8);ADV('ada','abilene')},
   next:()=>say(T,t(`书摆在收银台旁边，第一周就送光了。有人在网上贴了一张照片：小孩一手拿着书，一手拿着你的葡式蛋挞，配文“这家店有自己的童话”。`,`The books sit by the register and are gone in a week. Someone posts a photo online: a child with the book in one hand and one of your custard tarts in the other, captioned "This place has its own fairy tale."`,`Os livros ficam ao pé da caixa e desaparecem numa semana. Alguém publica uma fotografia: uma criança com o livro numa mão e um pastel de nata teu na outra, com a legenda «Este sítio tem o seu próprio conto de fadas».`),t(`−$200 · 口碑 +3 · 线上评分 +8`,`−$200 · Reputation +3 · Online +8`,`−$200 · Reputação +3 · Online +8`))}]);
 return sc(T,C.abilene,[P3([`艾达在画下一本书：一个在阿比林空军基地长大、想开飞机的小女孩。她说要借你的脸画那个“很帅但很笨的教官”。`,`艾达带你去看新装上的铜像，摸了摸它的鼻子：“摸了会有好运，这是我编的。”`,`艾达说她爸收到戴尔牧师的回信了，两个老头准备一起去钓鱼。`],[`Ada's drawing her next book: a little girl who grows up by the Abilene air base and wants to fly. She wants to borrow your face for "the handsome but dim instructor."`,`Ada takes you to see a newly installed bronze and rubs its nose. "Good luck if you touch it. I made that up."`,`Ada says her dad got a letter back from Pastor Dale — the two old men are planning a fishing trip.`],[`A Ada está a desenhar o próximo livro: uma menina que cresce junto à base aérea de Abilene e quer pilotar. Quer usar a tua cara para «o instrutor bonito mas tontinho».`,`A Ada leva-te a ver uma estátua de bronze nova e esfrega-lhe o nariz. «Dá sorte se lhe tocares. Fui eu que inventei.»`,`A Ada conta que o pai recebeu resposta do Pastor Dale — os dois velhotes vão juntos à pesca.`])],[
  {t:t(`陪她画一会儿`,`Keep her company while she draws`,`Fazer-lhe companhia enquanto desenha`),fx:()=>{stamp('ada');addLike('ada',1);stat('charme',1)}}]);
}

/* ---------------- LUPE (Del Rio & Seminole Canyon) ---------------- */
function lupeScene(){const s=ST('lupe'),T=t(`岩画向导`,`The rock-art guide`,`A guia da arte rupestre`);
 if(s===0)return sc(T,C.delrio,[
  t(`锡米诺尔峡谷的小路往下走，石灰岩被晒得发白。峡壁下面有一个巨大的岩棚，像石头张开的嘴。卢佩戴着宽檐帽，六十多岁，走路比你快。“这里叫费特·贝尔岩棚。”她用手电照着岩壁：红色、黑色、黄色的人形，有的长着鹿角，有的张开手臂飞起来。“大约四千年前画的。比你们的里斯本老，孩子。”`,`The trail drops into Seminole Canyon, the limestone bleached white by the sun. Under the canyon wall opens a huge rock shelter, like a stone mouth. Lupe, sixty-something in a wide-brimmed hat, walks faster than you. "This is Fate Bell Shelter." Her flashlight plays over the rock: red, black and yellow figures, some with antlers, some with arms spread as if flying. "Painted about four thousand years ago. Older than your Lisbon, mijo."`,`O trilho desce para o Seminole Canyon, o calcário branqueado pelo sol. Debaixo da parede do desfiladeiro abre-se um abrigo rochoso enorme, como uma boca de pedra. A Lupe, de sessenta e tal anos e chapéu de aba larga, anda mais depressa do que tu. «Isto é o abrigo Fate Bell.» A lanterna percorre a rocha: figuras vermelhas, pretas e amarelas, algumas com hastes de veado, outras de braços abertos como se voassem. «Pintadas há uns quatro mil anos. Mais velhas do que a tua Lisboa, filho.»`),
  t(`“没人知道他们叫自己什么，”她说，“可他们知道：画下来，就不会被忘掉。”`,`"Nobody knows what they called themselves," she says. "But they knew this much: paint it, and you won't be forgotten."`,`«Ninguém sabe como se chamavam a si próprios», diz. «Mas sabiam isto: pinta, e não serás esquecido.»`)],[
  {t:t(`问她：那些长着鹿角的人是谁？`,`Ask her: who are the figures with antlers?`,`Perguntar-lhe: quem são as figuras com hastes?`),fx:()=>{rel('lupe').met=true;addLike('lupe',2);stat('tex',2);ADV('lupe','delrio');log('在锡米诺尔峡谷认识了向导卢佩','Met Lupe, a guide, at Seminole Canyon','Conheceste a Lupe, guia, em Seminole Canyon')},
   next:()=>say(T,t(`“有人说是巫师，在两个世界之间走来走去。”她关掉手电，“我觉得，他们是想家的人。想着一个回不去的地方，就把自己画成能飞的样子。”下山时她说，下周志愿者要去阿米斯塔德水库捡垃圾，“你会做饭？那就来。”`,`"Some say shamans, walking between two worlds." She switches off the light. "Me, I think they were homesick. Thinking of a place they couldn't get back to, so they painted themselves able to fly." On the way down she says the volunteers are cleaning up Amistad Reservoir next week. "You cook? Then come."`,`«Há quem diga que são xamãs, a andar entre dois mundos.» Apaga a lanterna. «Eu acho que tinham saudades. Pensavam num sítio para onde não podiam voltar, e pintavam-se capazes de voar.» Na descida diz que os voluntários vão limpar a albufeira de Amistad na semana seguinte. «Sabes cozinhar? Então vem.»`),t(`认识了卢佩 · 德州味 +2`,`Met Lupe · Texanness +2`,`Conheceste a Lupe · Texanidade +2`))},
  {t:t(`安静地看，什么也不说`,`Look in silence and say nothing`,`Olhar em silêncio, sem dizer nada`),fx:()=>{rel('lupe').met=true;addTrust('lupe',2);stat('saud',-2);ADV('lupe','delrio');log('在锡米诺尔峡谷认识了向导卢佩','Met Lupe, a guide, at Seminole Canyon','Conheceste a Lupe, guia, em Seminole Canyon')},
   next:()=>say(T,t(`岩棚里很凉，风从峡谷底吹上来。你站了很久。卢佩没有催你，最后只说：“大部分游客五分钟就要走。你不一样。”她给了你一张手写的电话：“下次来，帮我做饭。”`,`It's cool in the shelter; wind rises from the canyon floor. You stand there a long time. Lupe doesn't hurry you. At last she only says, "Most visitors want to leave after five minutes. You're different." She gives you a handwritten number. "Next time, come cook for me."`,`Está fresco no abrigo; o vento sobe do fundo do desfiladeiro. Ficas ali muito tempo. A Lupe não te apressa. Por fim diz só: «A maioria dos visitantes quer ir-se embora ao fim de cinco minutos. Tu és diferente.» Dá-te um número escrito à mão. «Da próxima vez vem cozinhar para mim.»`),t(`认识了卢佩 · 信任 +2 · 乡愁 −2`,`Met Lupe · Trust +2 · Homesickness −2`,`Conheceste a Lupe · Confiança +2 · Saudade −2`))}]);
 if(s===1)return sc(T,C.delrio,[
  t(`阿米斯塔德水库的水是一种不像真的蓝绿色。大坝横在格兰德河上，一半在美国，一半在墨西哥；“阿米斯塔德”在西语里是“友谊”。二十几个志愿者沿着湖岸捡塑料瓶和渔线，卢佩在野餐桌边支起一个烤架，冲你招手。`,`Amistad Reservoir is a blue-green that doesn't look real. The dam spans the Rio Grande, half in the United States and half in Mexico; amistad is Spanish for friendship. Twenty-odd volunteers comb the shore for plastic bottles and fishing line, and Lupe, by a picnic table, sets up a grill and waves you over.`,`A albufeira de Amistad tem um azul-esverdeado que não parece verdadeiro. A barragem atravessa o rio Grande, metade nos Estados Unidos e metade no México; amistad quer dizer amizade em espanhol. Uns vinte voluntários percorrem a margem a apanhar garrafas e fio de pesca, e a Lupe, ao pé de uma mesa de piquenique, monta uma grelha e acena-te.`),
  t(`烤肉的时候她说：“我哥哥鲁本，七七年过河去北边干活，说一年就回来。后来寄过几张明信片，再后来就没有了。我妈到死都把他的房间留着。”她把一块肉翻过来，“你为什么一个人在德州？”`,`While the meat cooks she says, "My brother Rubén went north to work in seventy-seven. Said he'd be back in a year. A few postcards came, then nothing. My mother kept his room till the day she died." She flips a piece of meat. "Why are you in Texas all by yourself?"`,`Enquanto a carne grelha, diz: «O meu irmão Rubén foi para norte trabalhar em setenta e sete. Disse que voltava ao fim de um ano. Vieram uns postais e depois nada. A minha mãe guardou-lhe o quarto até ao dia em que morreu.» Vira um pedaço de carne. «Porque é que estás sozinho no Texas?»`)],[
  {t:t(`讲若泽：你舅舅也是这样，走了就再没回家`,`Tell her about José: your uncle did the same — left and never went home`,`Falar do José: o teu tio fez o mesmo — partiu e nunca mais voltou`),fx:()=>{addTrust('lupe',3);stat('saud',3);S.rep+=1;ADV('lupe','delrio')},
   next:()=>say(T,t(`卢佩听完，把夹子放下。“那你就是那张没寄出的明信片，”她说，“替他回去了一半。”志愿者们排队来拿烤肉，有人说这是他们吃过最好的湖边午饭。`,`Lupe listens, then sets down the tongs. "Then you're the postcard he never sent," she says. "You've gone halfway home for him." The volunteers line up for the meat; someone says it's the best lakeside lunch they've ever had.`,`A Lupe ouve e pousa a pinça. «Então tu és o postal que ele nunca mandou», diz. «Já fizeste metade do caminho de volta por ele.» Os voluntários fazem fila para a carne; alguém diz que foi o melhor almoço à beira do lago que já comeram.`),t(`卢佩信任 +3 · 乡愁 +3 · 口碑 +1`,`Lupe trust +3 · Homesickness +3 · Reputation +1`,`Confiança da Lupe +3 · Saudade +3 · Reputação +1`))},
  {t:t(`笑着说：为了德州的烤肉，和德州的天空`,`Smile and say: for Texas barbecue and the Texas sky`,`Sorrir e dizer: pelo churrasco e pelo céu do Texas`),fx:()=>{addLike('lupe',2);stat('tex',2);S.rep+=1;ADV('lupe','delrio')},
   next:()=>say(T,t(`卢佩笑了，没再问。可她把最好的一块肉夹到了你的盘子里，像对待一个还没准备好说实话的孩子。`,`Lupe laughs and doesn't ask again. But she puts the best piece of meat on your plate, the way you treat a kid who isn't ready to tell the truth yet.`,`A Lupe ri-se e não volta a perguntar. Mas põe-te o melhor pedaço de carne no prato, como se faz a um miúdo que ainda não está pronto para dizer a verdade.`),t(`卢佩好感 +2 · 德州味 +2`,`Lupe liking +2 · Texanness +2`,`Afeição da Lupe +2 · Texanidade +2`))}]);
 if(s===2)return sc(T,C.delrio,[
  t(`傍晚，卢佩带你到佩科斯河大桥边的观景台。90 号国道从桥上过，人们常说这是德州最高的公路桥。下面很远的地方，佩科斯河绿得发黑，在峡谷里拐了一个弯，流进格兰德河。`,`At dusk Lupe takes you to the overlook by the Pecos River High Bridge. US-90 crosses on it; folks say it's the highest highway bridge in Texas. Far below, the Pecos runs green almost to black, bends in its canyon and flows into the Rio Grande.`,`Ao fim da tarde a Lupe leva-te ao miradouro junto à ponte alta do rio Pecos. A US-90 passa por cima; diz-se que é a ponte rodoviária mais alta do Texas. Lá muito em baixo, o Pecos corre de um verde quase negro, faz uma curva no desfiladeiro e entra no rio Grande.`),
  t(`“我找到鲁本了。”她说，声音很平，“在加州，一家养老院。他七十岁了，记不清事。护士说，他每天问‘妈妈的房间还在吗’。”她看着你，“你妈妈呢？你多久没给她打电话了？”`,`"I found Rubén," she says, her voice very level. "In California, a nursing home. He's seventy and his memory's going. The nurse says every day he asks, 'Is Mama's room still there?'" She looks at you. "And your mother? How long since you called her?"`,`«Encontrei o Rubén», diz, com a voz muito serena. «Na Califórnia, num lar. Tem setenta anos e já não se lembra bem das coisas. A enfermeira diz que todos os dias pergunta "o quarto da mãe ainda lá está?"» Olha para ti. «E a tua mãe? Há quanto tempo não lhe ligas?»`)],[
  {t:t(`当着她的面给母亲打电话`,`Call your mother right there`,`Ligar à tua mãe ali mesmo`),fx:()=>{addTrust('lupe',3);stat('saud',-6);stat('charme',1);ADV('lupe','delrio');log('在佩科斯河大桥边给母亲打了电话','Called your mother from the Pecos River bridge','Ligaste à tua mãe junto à ponte do Pecos')},
   next:()=>say(T,t(`里斯本已经是半夜了。妈妈接起电话的第一句话是：“出什么事了？”你说没事，就是想听听你的声音。电话那头安静了很久，然后她笑了，笑着笑着哭了。卢佩走开了几步，背对着你看河。`,`It's past midnight in Lisbon. The first thing your mother says is, "What's happened?" You say nothing's happened, you just wanted to hear her voice. A long silence on the line, then she laughs, and the laughing turns to crying. Lupe steps a few paces off and watches the river with her back to you.`,`Em Lisboa já passa da meia-noite. A primeira coisa que a tua mãe diz é: «O que é que aconteceu?» Dizes que não aconteceu nada, só querias ouvir a voz dela. Um longo silêncio, depois ela ri-se, e o riso passa a choro. A Lupe afasta-se uns passos e fica de costas a olhar para o rio.`),t(`卢佩信任 +3 · 乡愁 −6`,`Lupe trust +3 · Homesickness −6`,`Confiança da Lupe +3 · Saudade −6`))},
  {t:t(`说你会打的，但不是现在`,`Say you'll call — just not now`,`Dizer que vais ligar — mas não agora`),fx:()=>{addLike('lupe',1);stat('saud',3);ADV('lupe','delrio')},
   next:()=>say(T,t(`卢佩点点头，没有勉强你。“我妈也总说‘以后’。”她把帽子按低一点，“以后是一个很远的地方，孩子。比加州还远。”`,`Lupe nods and doesn't push. "My mother always said 'later' too." She tugs her hat brim lower. "Later is a long way off, mijo. Farther than California."`,`A Lupe acena e não insiste. «A minha mãe também dizia sempre "depois".» Puxa a aba do chapéu para baixo. «O depois fica muito longe, filho. Mais longe do que a Califórnia.»`),t(`卢佩好感 +1 · 乡愁 +3`,`Lupe liking +1 · Homesickness +3`,`Afeição da Lupe +1 · Saudade +3`))}]);
 if(s===3)return sc(T,C.delrio,[
  t(`峡谷的营地上，卢佩在地上挖了一个浅坑，铺上牧豆树的炭，把一口黑铁锅埋进去，锅盖上也堆满炭。“营地面包，”她说，“牛仔赶牛的时候在野外做的，后来成了德州的州面包。面粉、发粉、盐、一点猪油，就这么简单。”`,`At the canyon campground Lupe digs a shallow pit, lines it with mesquite coals, sets a black iron Dutch oven in it and heaps more coals on the lid. "Pan de campo," she says. "Camp bread. Vaqueros made it out on the cattle drives, and later it became the official state bread of Texas. Flour, baking powder, salt, a little lard. That simple."`,`No parque de campismo do desfiladeiro, a Lupe cava uma cova rasa, forra-a com brasas de algaroba, enterra uma panela de ferro preta e cobre a tampa com mais brasas. «Pão de acampamento», diz. «Os vaqueiros faziam-no no campo quando levavam o gado, e depois tornou-se o pão oficial do estado do Texas. Farinha, fermento, sal, um pouco de banha. Simples assim.»`),
  t(`“下个月我去加州看鲁本，”她说，“我会带一个这样的面包。也许他记不住我，可他会记住这个味道。”`,`"Next month I'm going to California to see Rubén," she says. "I'll take one of these. Maybe he won't remember me, but he'll remember the taste."`,`«No mês que vem vou à Califórnia ver o Rubén», diz. «Levo-lhe um destes. Pode não se lembrar de mim, mas vai lembrar-se do sabor.»`)],[
  {t:t(`跟她学做营地面包`,`Learn to make the camp bread with her`,`Aprender com ela a fazer o pão de acampamento`),fx:()=>{learnDish('pandecampo');addTrust('lupe',2);addLike('lupe',2);stat('oficio',2);stat('saud',-3);ADV('lupe','delrio')},
   next:()=>say(T,t(`面包从锅里出来，圆圆的，金黄色，像一个小太阳。卢佩掰了一半给你，一半用布包好。“去圣鲁伊斯的那个节日，我也想去。”她说，“我带一锅这个。”`,`The bread comes out of the pot round and golden, like a small sun. Lupe breaks off half for you and wraps the other half in a cloth. "That festival in San Luís — I'd like to come," she says. "I'll bring a pot of this."`,`O pão sai da panela redondo e dourado, como um pequeno sol. A Lupe parte metade para ti e embrulha a outra metade num pano. «Essa festa em San Luís — gostava de ir», diz. «Levo uma panela disto.»`),t(`学会：营地面包 · 手艺 +2 · 乡愁 −3`,`Learned: pan de campo · Craft +2 · Homesickness −3`,`Aprendeste: pão de acampamento · Ofício +2 · Saudade −3`))},
  {t:t(`请她把面包带到圣安东尼节来`,`Ask her to bring the bread to the Santo António festival`,`Pedir-lhe que leve o pão à festa de Santo António`),fx:()=>{learnDish('pandecampo');S.flags.tx8_lupeFest=1;addLike('lupe',3);stat('saud',-2);ADV('lupe','delrio');log('卢佩答应带营地面包来圣安东尼节','Lupe promised to bring camp bread to the Santo António festival','A Lupe prometeu levar pão de acampamento à festa de Santo António')},
   next:()=>say(T,[t(`“圣安东尼？”她笑了，“我们这边的女孩也向他求丈夫。好，我去。”她把锅盖上的炭拨开，香味一下子冒出来，“看好了，你也要学会。”`,`"Saint Anthony?" She laughs. "Our girls pray to him for husbands too. All right, I'll come." She brushes the coals off the lid and the smell bursts out. "Watch close — you're learning this too."`,`«Santo António?» Ri-se. «As nossas raparigas também lhe pedem marido. Está bem, eu vou.» Afasta as brasas da tampa e o cheiro salta cá para fora. «Vê bem — tu também vais aprender.»`),t(`她又塞给你一块小石头，上面用红颜料画着一个张开手臂的小人。“画下来，就不会被忘掉。”`,`She presses a small stone into your hand, a little figure with spread arms painted on it in red. "Paint it, and you won't be forgotten."`,`Põe-te na mão uma pedrinha com uma figura de braços abertos pintada a vermelho. «Pinta, e não serás esquecido.»`)],t(`学会：营地面包 · 卢佩会来圣安东尼节`,`Learned: pan de campo · Lupe will come to the festival`,`Aprendeste: pão de acampamento · A Lupe vem à festa`))}]);
 return sc(T,C.delrio,[P3([`卢佩刚从加州回来。“鲁本吃了三块面包，”她说，“然后叫了我的名字。”`,`卢佩在岩棚前给一群小学生讲课，看见你，冲你眨了眨眼。`,`卢佩带你去圣费利佩泉，说这股泉水从来没断过，德尔里奥就是靠它长起来的。`],[`Lupe's just back from California. "Rubén ate three pieces of bread," she says. "Then he said my name."`,`Lupe is giving a talk to a group of schoolkids at the shelter. She sees you and winks.`,`Lupe takes you to San Felipe Springs and says the water has never once stopped — Del Rio grew up because of it.`],[`A Lupe acabou de voltar da Califórnia. «O Rubén comeu três pedaços de pão», diz. «E depois disse o meu nome.»`,`A Lupe está a dar uma explicação a um grupo de alunos no abrigo. Vê-te e pisca-te o olho.`,`A Lupe leva-te às nascentes de San Felipe e diz que a água nunca parou — Del Rio cresceu por causa dela.`])],[
  {t:t(`陪她走走`,`Walk with her`,`Passear com ela`),fx:()=>{stamp('lupe');addLike('lupe',1);stat('saud',-1)}}]);
}

/* ================= CITIES ================= */
Object.assign(CITIES,{
/* ---------------- MIDLAND–ODESSA ---------------- */
permian:{n:C.permian,region:'west',miles:300,trip:'overnight',hotel:140,via:['i35','i20'],
 desc:t(`二叠纪盆地的双子城：米德兰的玻璃大楼像平原上竖起的一排钞票，敖德萨的抽油机从城边一直点头点到地平线。`,`The twin cities of the Permian Basin: Midland's glass towers stand on the plain like a row of banknotes, and Odessa's pumpjacks nod from the edge of town to the horizon.`,`As cidades gémeas da Bacia do Pérmico: as torres de vidro de Midland erguem-se na planície como uma fila de notas, e as bombas de petróleo de Odessa acenam da beira da cidade até ao horizonte.`),
 arrive:()=>{if(VIS('permian')<=1){stat('tex',3);return [t(`过了阿比林，树越来越少，最后连灌木都矮下去。然后抽油机出现了，一台、十台、一百台，在夕阳里一上一下，像一群喝水的铁鸟。公路上全是白色皮卡，车斗里装着管子和工具箱。旅店的价钱贵得让你以为看错了。`,`Past Abilene the trees thin out until even the brush goes low. Then the pumpjacks appear — one, ten, a hundred — rising and dipping in the sunset like iron birds drinking. The highway is all white pickups, beds loaded with pipe and toolboxes. The motel prices are so high you think you've misread them.`,`Depois de Abilene as árvores rareiam até o mato ficar rasteiro. Depois aparecem as bombas de petróleo — uma, dez, cem — a subir e a descer ao pôr do sol como pássaros de ferro a beber. A estrada é só carrinhas brancas, com tubos e caixas de ferramentas atrás. Os preços dos motéis são tão altos que pensas que leste mal.`)]}
  return [inSeason(25,36)?t(`冬天的盆地风很硬，抽油机上挂着冰。`,`The winter Basin wind is hard; ice hangs off the pumpjacks.`,`O vento de inverno na Bacia é duro; há gelo pendurado nas bombas.`):P3([`又是满天的沙尘，太阳变成一个橘色的硬币。`,`抽油机还在点头，好像一直在等你回来。`],[`Dust fills the sky again; the sun is an orange coin.`,`The pumpjacks are still nodding, as if they've been waiting for you.`],[`O pó volta a encher o céu; o sol é uma moeda cor de laranja.`,`As bombas continuam a acenar, como se estivessem à tua espera.`])]},
 locs:[
  {id:'tx8_truckstop',n:t(`20 号州际公路边的卡车停车场`,`The I-20 truck stop`,`A área de camiões da I-20`),acts:[
   {id:'tx8_jesse',n:t(`找那个拉砂的年轻司机`,`Look for the young sand hauler`,`Procurar o jovem camionista da areia`),cost:2,req:STAGE('jesse','permian',4),tip:STORYTIP,run:jesseScene},
   {id:'tx8_mancamp',n:t(`在工人营地外面摆摊`,`Set up a stall outside a man camp`,`Montar uma banca à porta de um acampamento de trabalhadores`),cost:2,req:daily('mancamp'),tip:t(`油田工人饿、钱多：高价卖掉库存`,`Hungry roughnecks with cash: sell stock at a premium`,`Petroleiros com fome e dinheiro: vender a mercadoria caro`),run:()=>sc(t(`工人营地`,`The man camp`,`O acampamento`),C.permian,[t(`一排排白色的活动板房，住着几百个从全国各地来的油田工人。换班的时候，皮卡排出去半英里。食堂的菜他们早就吃腻了。`,`Rows of white modular bunkhouses house a few hundred oilfield hands from all over the country. At shift change the pickups queue half a mile. They got sick of the canteen food long ago.`,`Filas de módulos brancos alojam umas centenas de trabalhadores do petróleo vindos de todo o país. Na mudança de turno as carrinhas fazem fila de meia milha. Há muito que se fartaram da comida da cantina.`)],[
     {t:t(`开卖（盆地物价，贵一点也有人买）`,`Open up (Basin prices — they'll pay)`,`Abrir (preços da Bacia — eles pagam)`),fx:()=>stamp('mancamp'),next:()=>pop(t(`工人营地`,`The man camp`,`O acampamento`),14,1.6,`一个从路易斯安那来的工人吃完说：“我在这儿干了八个月，这是第一口像家里的东西。”队伍一直排到天黑。`,`A hand from Louisiana finishes and says, "Eight months out here and that's the first bite that tasted like home." The line runs till dark.`,`Um trabalhador do Luisiana acaba e diz: «Oito meses aqui e foi a primeira dentada que me soube a casa.» A fila dura até escurecer.`)},
     {t:t(`算了`,`Never mind`,`Deixa estar`)}])},
   {id:'tx8_crew',n:t(`给钻井队接一单外烩`,`Cater for a drilling crew`,`Fazer o catering de uma equipa de perfuração`),cost:3,req:AND(once('crew'),()=>(S.stats.oficio>=40||charm()>=55)||NEED(t(`手艺 40 或魅力 55`,`Craft 40 or Charm 55`,`Ofício 40 ou Charme 55`))),tip:t(`一次性大单`,`One big order`,`Uma encomenda grande`),run:()=>sc(t(`钻井队`,`The drilling crew`,`A equipa de perfuração`),C.permian,[t(`一个钻井队打完一口井，要庆祝。队长是个满脸胡子的大个子：“四十个人，肉要多，别给我们弄沙拉。”`,`A drilling crew has finished a well and wants to celebrate. The tool pusher is a big bearded man. "Forty men. Lots of meat. Don't bring us no salad."`,`Uma equipa de perfuração acabou um poço e quer festejar. O encarregado é um grandalhão de barba. «Quarenta homens. Muita carne. Nada de saladas.»`)],[
     {t:t(`烤一整夜：葡式香肠、猪颈肉、蒜香牛肉`,`Grill all night: chouriço, pork neck, garlic beef`,`Grelhar a noite toda: chouriço, cachaço, vaca com alho`),fx:()=>{S.flags.tx8_crew=1;S.cash+=380;S.wk.rev+=380;S.rep+=2;ONL(3);stat('tex',2);log('给敖德萨钻井队外烩 +$380','Catered an Odessa drilling crew +$380','Catering para uma equipa de perfuração de Odessa +$380')},next:()=>say(t(`钻井队`,`The drilling crew`,`A equipa de perfuração`),t(`天亮的时候，四十个人都吃撑了。队长把一卷钞票塞给你：“下次我们队去中部德州干活，就去你那儿吃。”`,`By dawn all forty are stuffed. The tool pusher presses a roll of bills on you. "Next time our crew works Central Texas, we eat at your place."`,`De madrugada estão os quarenta empanturrados. O encarregado mete-te um rolo de notas na mão. «Da próxima vez que a equipa trabalhar no Texas Central, comemos na tua casa.»`),t(`现金 +$380 · 口碑 +2 · 德州味 +2`,`Cash +$380 · Reputation +2 · Texanness +2`,`Dinheiro +$380 · Reputação +2 · Texanidade +2`))},
     {t:t(`算了，四十个人太多`,`Pass — forty is too many`,`Não — quarenta é demais`)}])}
  ]},
  {id:'tx8_museum',n:t(`米德兰的石油博物馆`,`The petroleum museum in Midland`,`O museu do petróleo em Midland`),acts:[
   {id:'tx8_rigs',n:t(`看老钻机和古海洋`,`See the old rigs and the ancient sea`,`Ver as sondas antigas e o mar antigo`),cost:1,run:()=>{const w=W();return sc(t(`石油博物馆`,`The petroleum museum`,`O museu do petróleo`),C.permian,[
     t(`博物馆外面的空地上摆满了退役的钻机和抽油机，像一座铁的动物园。里面有一面墙讲这片土地的来历：两亿多年前，这里是一片温暖的浅海，珊瑚礁和小生物的尸体沉在海底，压了几亿年，变成了今天的石油。`,`Outside the museum, a lot full of retired drilling rigs and pumpjacks, like an iron zoo. Inside, a wall explains the land: more than two hundred million years ago this was a warm shallow sea; reefs and tiny creatures sank to the bottom, pressed for ages, and became today's oil.`,`À porta do museu, um terreno cheio de sondas e bombas reformadas, como um jardim zoológico de ferro. Lá dentro, uma parede conta a história da terra: há mais de duzentos milhões de anos isto era um mar quente e pouco fundo; recifes e bichinhos afundaram, foram comprimidos durante eras e tornaram-se o petróleo de hoje.`),
     ...(w?[t(`${SH(w)}站在那块古海洋的示意图前：“所以，你在沙漠里也找到了海。”`,`${SH(w)} stands before the map of the ancient sea. "So you found the sea even in the desert."`,`${SH(w)} para em frente ao mapa do mar antigo. «Então até no deserto encontraste o mar.»`)]:[t(`你想：原来这片沙漠底下，也曾经是海。`,`You think: so under this desert, too, there was once a sea.`,`Pensas: afinal, debaixo deste deserto também houve um mar.`)])],[
     {t:t(`想一想里斯本的海`,`Think of the sea at Lisbon`,`Pensar no mar de Lisboa`),fx:()=>{stat('saud',2);stat('charme',1);if(w)addLike(w,1)}},
     {t:t(`听退休的老钻工讲盆地的繁荣和萧条`,`Listen to a retired driller on the Basin's booms and busts`,`Ouvir um velho perfurador falar dos altos e baixos da Bacia`),fx:()=>{stat('tex',3);if(w)addTrust(w,0.5)},next:()=>say(t(`老钻工`,`The old driller`,`O velho perfurador`),t(`“八十年代油价跌的时候，米德兰的银行一家接一家倒，”他说，“人们在车尾贴纸上写：主啊，再给我一次繁荣，这次我保证不乱花。”他笑得很大声，“没人守住承诺。”`,`"When oil crashed in the eighties, Midland banks went under one after another," he says. "Folks put bumper stickers on their trucks: Lord, give me one more boom, I promise not to blow it this time." He laughs loud. "Nobody kept the promise."`,`«Quando o petróleo caiu nos anos oitenta, os bancos de Midland foram falindo um atrás do outro», diz. «As pessoas punham autocolantes nos carros: Senhor, dá-me só mais um boom, prometo não o estragar desta vez.» Ri-se alto. «Ninguém cumpriu.»`),t(`德州味 +3`,`Texanness +3`,`Texanidade +3`))}])}}
  ]},
  {id:'tx8_crater',n:t(`敖德萨陨石坑与“巨石阵”`,`The Odessa meteor crater & the "Stonehenge"`,`A cratera de Odessa e o «Stonehenge»`),acts:[
   {id:'tx8_meteor',n:t(`走一圈陨石坑`,`Walk the meteor crater`,`Dar a volta à cratera`),cost:1,run:()=>sc(t(`陨石坑`,`The crater`,`A cratera`),C.permian,[t(`城西南的平原上，一个浅浅的大碗陷进地里。几万年前一块铁陨石砸下来，碎成好几块。现在坑底长着牧豆树，长耳大野兔从你脚边窜过去。不远处的大学校园里，还有人用石灰岩照着英国的巨石阵造了一个复制品，在西德州的风里站着，很认真的样子。`,`On the plain southwest of town, a broad shallow bowl sinks into the ground. Tens of thousands of years ago an iron meteorite slammed down here and broke into pieces. Now mesquite grows on the floor and jackrabbits bolt past your feet. Not far off, on a university campus, someone built a limestone copy of England's Stonehenge, standing very earnestly in the West Texas wind.`,`Na planície a sudoeste da cidade, uma tigela larga e pouco funda afunda-se no chão. Há dezenas de milhares de anos caiu aqui um meteorito de ferro e partiu-se em pedaços. Agora crescem algarobas no fundo e as lebres disparam-te aos pés. Não muito longe, num campus universitário, alguém construiu em calcário uma cópia do Stonehenge inglês, muito compenetrada ao vento do Oeste do Texas.`)],[
     {t:t(`去巨石阵那儿拍张傻照片发给鲁伊`,`Take a silly photo at the Stonehenge and send it to Rui`,`Tirar uma fotografia parva no Stonehenge e mandar ao Rui`),fx:()=>{stat('saud',-2);stat('charme',1)},next:()=>say(t(`巨石阵`,`Stonehenge`,`Stonehenge`),t(`鲁伊回了一句：“你在英国？”你说在德州。他回：“德州到底有什么没有？”`,`Rui writes back: "You're in England?" You say Texas. He replies: "Is there anything Texas doesn't have?"`,`O Rui responde: «Estás em Inglaterra?» Dizes que estás no Texas. Ele responde: «Há alguma coisa que o Texas não tenha?»`),t(`乡愁 −2 · 魅力 +1`,`Homesickness −2 · Charm +1`,`Saudade −2 · Charme +1`))},
     {t:t(`在坑边坐着，看风把沙子吹过平原`,`Sit at the rim and watch the wind push sand across the plain`,`Sentar na borda a ver o vento empurrar a areia pela planície`),fx:()=>{stat('tex',2);stat('saud',1)}}])},
   {id:'tx8_friday',n:t(`星期五夜里的高中橄榄球赛`,`Friday-night high-school football`,`Futebol americano do liceu à sexta à noite`),cost:2,req:AND(SEAS(13,24,`只在秋天（第 13–24 周）`,`Autumn only (weeks 13–24)`,`Só no outono (semanas 13–24)`),()=>S.day===5||t(`只在星期五`,`Fridays only`,`Só à sexta-feira`),daily('friday')),tip:t(`在停车场卖掉库存`,`Sell stock in the parking lot`,`Vender a mercadoria no parque`),run:()=>sc(t(`星期五夜里`,`Friday night`,`Sexta à noite`),C.permian,[t(`敖德萨的高中球场灯一亮，整座城都来了。人们常说这里把高中橄榄球当宗教——有人写过一本关于这里的书，后来拍成了电影和电视剧。停车场里，几十家人支起烤架，喇叭里放着军乐队的鼓点。`,`When the Odessa high-school stadium lights come on, the whole town shows up. Folks say football here is a religion — someone wrote a book about this place that became a movie and a TV series. In the parking lot dozens of families fire up grills while the marching band's drums boom over the speakers.`,`Quando se acendem as luzes do estádio do liceu de Odessa, aparece a cidade inteira. Diz-se que aqui o futebol americano é uma religião — alguém escreveu um livro sobre este sítio que deu um filme e uma série. No parque de estacionamento, dezenas de famílias acendem grelhas e os tambores da banda ecoam pelos altifalantes.`)],[
     {t:t(`在停车场开卖`,`Sell in the parking lot`,`Vender no parque`),fx:()=>{stamp('friday');stat('tex',2)},next:()=>pop(t(`星期五夜里`,`Friday night`,`Sexta à noite`),12,1.4,`中场休息时你的队伍比厕所的还长。一个戴着球队帽的老太太说：“孩子，你赢了今晚。”`,`At halftime your line is longer than the one for the restrooms. An old lady in a team cap says, "Honey, you won tonight."`,`No intervalo a tua fila é maior do que a das casas de banho. Uma senhora de boné da equipa diz: «Querido, quem ganhou esta noite foste tu.»`)},
     {t:t(`只去看球`,`Just watch the game`,`Só ver o jogo`),fx:()=>{stamp('friday');stat('tex',3);stat('saud',-2)}}])}
  ]},
  {id:'tx8_dunes',n:t(`莫纳汉斯沙丘州立公园`,`Monahans Sandhills State Park`,`Parque Estadual de Monahans Sandhills`),acts:[
   {id:'tx8_sled',n:t(`租个圆盘，从沙丘上滑下去`,`Rent a disc and slide down a dune`,`Alugar um disco e escorregar por uma duna`),cost:2,run:()=>{const w=W();return sc(t(`白色沙丘`,`White dunes`,`Dunas brancas`),C.permian,[
     t(`公园管理处出租塑料圆盘，涂一层蜡就能从沙丘上滑下去。沙丘有的高过两层楼，被风推着慢慢走。沙子凉凉的、细得像面粉。远处，压裂砂矿的传送带在地平线上一刻不停。`,`The park office rents plastic discs; wax one up and you can slide down the dunes. Some are taller than a two-story house, crawling slowly in the wind. The sand is cool and fine as flour. Far off on the horizon, a frac-sand mine's conveyors run without stopping.`,`A receção do parque aluga discos de plástico; enceras um e podes escorregar pelas dunas. Algumas são mais altas do que uma casa de dois andares e avançam devagar com o vento. A areia é fresca e fina como farinha. Lá longe no horizonte, os tapetes de uma mina de areia de fracking não param.`),
     ...(w?[t(`${SH(w)}第一次滑下来，满头满脸都是沙，笑得爬不起来。`,`${SH(w)} comes down the first time with sand in their hair and face, laughing too hard to get up.`,`${SH(w)} desce a primeira vez com areia no cabelo e na cara, a rir tanto que não se consegue levantar.`)]:[])],[
     {t:t(`再爬上去滑一次！`,`Climb back up and go again!`,`Subir outra vez e repetir!`),fx:()=>{stat('saud',-3);stat('tex',1);if(w){addLike(w,2);addTrust(w,0.5)}},next:()=>say(t(`白色沙丘`,`White dunes`,`Dunas brancas`),t(`第五次你滑到了沙丘底下，抬头一看，天蓝得像阿尔法马屋顶上的天。你一个人在沙子里躺了很久。`,`The fifth run takes you all the way to the bottom. You look up: the sky is as blue as the sky over the rooftops of Alfama. You lie in the sand a long time.`,`À quinta descida chegas lá abaixo. Olhas para cima: o céu está tão azul como por cima dos telhados de Alfama. Ficas muito tempo deitado na areia.`),t(`乡愁 −3`,`Homesickness −3`,`Saudade −3`))},
     {t:t(`看着远处的砂矿想事情`,`Watch the far-off sand mine and think`,`Olhar para a mina ao longe e pensar`),fx:()=>{stat('tex',2);if(ST('jesse')>=2)stat('charme',1)}}])}}
  ]}
 ]
},
/* ---------------- SAN ANGELO ---------------- */
sanangelo:{n:C.sanangelo,region:'west',miles:190,trip:'overnight',hotel:85,via:['us190'],
 desc:t(`康乔河边的西德州小城：十九世纪的骑兵堡、河边步道、满街涂得花花绿绿的羊雕像，和老羊毛仓库里散不去的羊脂味。`,`A West Texas town on the Concho River: a nineteenth-century cavalry fort, a river walk, painted sheep statues all over town, and the smell of lanolin that never quite leaves the old wool warehouses.`,`Uma cidade do Oeste do Texas junto ao rio Concho: um forte de cavalaria do século XIX, um passeio ribeirinho, estátuas de ovelhas pintadas por todo o lado e o cheiro a lanolina que nunca sai dos velhos armazéns de lã.`),
 arrive:()=>{if(VIS('sanangelo')<=1){stat('tex',2);return [t(`190 号国道往西，山地渐渐平下去，变成一望无际的牧场：牧豆树、石头围栏、一群群绵羊和山羊。进城时，路边的第一只羊雕像全身画满了蓝帽花，冲你咧嘴笑。`,`West on US-190 the Hill Country flattens out into endless rangeland: mesquite, stone fences, flocks of sheep and goats. Coming into town, the first sheep statue by the road is painted all over with bluebonnets and grins at you.`,`Para oeste pela US-190, as colinas vão alisando até virarem pastagens sem fim: algarobas, muros de pedra, rebanhos de ovelhas e cabras. À entrada da cidade, a primeira estátua de ovelha à beira da estrada está pintada de tremoços-azuis e sorri-te.`)]}
  return [inSeason(33,36)?t(`牲畜展的季节，城里到处是拉着牲口的拖车和戴牛仔帽的小孩。`,`Stock-show season: trailers of livestock and kids in cowboy hats everywhere.`,`É a época da feira de gado: atrelados com animais e miúdos de chapéu de cowboy por todo o lado.`):inSeason(37,44)?t(`春天是剪羊毛的季节，牧场边的棚子里传出电剪的嗡嗡声。`,`Spring is shearing season; the buzz of clippers comes from the sheds by the ranches.`,`A primavera é época de tosquia; dos barracões dos ranchos vem o zumbido das tosquiadoras.`):t(`康乔河还是慢慢地流，河边的羊雕像又多了几只。`,`The Concho still flows slow, and there are a few more sheep statues by the river.`,`O Concho continua a correr devagar, e há mais umas ovelhas de estátua junto ao rio.`)]},
 locs:[
  {id:'tx8_warehouse',n:t(`老羊毛仓库`,`The old wool warehouses`,`Os velhos armazéns de lã`),acts:[
   {id:'tx8_walt',n:t(`去找那个摸羊毛的老人`,`Find the old man who grades wool by hand`,`Procurar o velho que classifica lã à mão`),cost:2,req:STAGE('waltk','sanangelo',4),tip:STORYTIP,run:waltScene},
   {id:'tx8_salebarn',n:t(`去牲畜拍卖场买肉`,`Buy meat at the livestock auction`,`Comprar carne no leilão de gado`),cost:1,req:daily('salebarn'),run:()=>sc(t(`拍卖场`,`The sale barn`,`O leilão`),C.sanangelo,[t(`拍卖师的嘴快得像机关枪，你一个字也没听懂，只看见牧场主们轻轻抬一下帽檐就成交了。拍卖场旁边的屠宰场直接卖分割好的牛肉。`,`The auctioneer's mouth runs like a machine gun; you don't catch a word, only ranchers tipping a hat brim to close a sale. The packing house next to the barn sells cut beef direct.`,`O leiloeiro fala como uma metralhadora; não percebes uma palavra, só vês os rancheiros a tocar na aba do chapéu para fechar negócio. O matadouro ao lado vende carne de vaca cortada diretamente.`)],[
     {t:t(`拿 10 份牛肉（七五折）`,`Take 10 beef (25% off)`,`Levar 10 de vaca (25% de desconto)`),fx:()=>stamp('salebarn'),next:()=>buy(t(`拍卖场`,`The sale barn`,`O leilão`),'beef',10,0.75,`屠宰场的老板看你挑肉的样子，又多送了一块骨头：“熬汤用。”`,`The packing-house boss watches how you pick and throws in a bone. "For stock."`,`O dono do matadouro vê como escolhes e oferece-te um osso. «Para o caldo.»`)},
     {t:t(`只看拍卖`,`Just watch the auction`,`Só ver o leilão`),fx:()=>{stamp('salebarn');stat('tex',2)}}])}
  ]},
  {id:'tx8_fort',n:t(`康乔堡`,`Fort Concho`,`Forte Concho`),acts:[
   {id:'tx8_fortwalk',n:t(`在老营房和阅兵场走一走`,`Walk the old barracks and parade ground`,`Percorrer as velhas casernas e a parada`),cost:1,run:()=>{const w=W();return sc(t(`康乔堡`,`Fort Concho`,`Forte Concho`),C.sanangelo,[
     t(`十九世纪六十年代建的骑兵堡，石灰岩的营房围着一大片阅兵场，保存得像昨天才有人离开。讲解牌上写着，这里驻扎过黑人骑兵——当地的原住民叫他们“水牛兵”。城就是在堡对岸长出来的。`,`A cavalry fort built in the 1860s, limestone barracks around a broad parade ground, kept as if the last soldiers left yesterday. The plaques say Black cavalry troopers were stationed here — the "Buffalo Soldiers," as the Native peoples called them. The town grew up across the river from the fort.`,`Um forte de cavalaria construído nos anos 1860, casernas de calcário à volta de uma grande parada, conservado como se os últimos soldados tivessem saído ontem. As placas contam que aqui estiveram tropas de cavalaria negras — os «Buffalo Soldiers», como lhes chamavam os povos nativos. A cidade cresceu do outro lado do rio, em frente ao forte.`),
     ...(w?[t(`${SH(w)}在一张老照片前站了很久：一排骑兵，背后是空荡荡的平原。“他们离家也很远。”`,`${SH(w)} stands a long time before an old photo: a line of troopers, empty plains behind them. "They were a long way from home too."`,`${SH(w)} fica muito tempo em frente a uma fotografia antiga: uma fila de soldados a cavalo, a planície vazia atrás. «Também estavam muito longe de casa.»`)]:[])],[
     {t:t(`读完所有的讲解牌`,`Read every plaque`,`Ler todas as placas`),fx:()=>{stat('tex',3);if(w)addTrust(w,1)}},
     {t:t(`在阅兵场上一个人站一会儿`,`Stand alone on the parade ground a while`,`Ficar um bocado sozinho na parada`),fx:()=>{stat('saud',2);stat('charme',1);if(w)addLike(w,1)}}])}},
   {id:'tx8_stockshow',n:t(`牲畜展外的烧烤比赛`,`The cook-off outside the stock show`,`O concurso de grelhados à porta da feira de gado`),cost:3,req:AND(SEAS(33,36,`只在牲畜展期间（第 33–36 周）`,`Only during the stock show (weeks 33–36)`,`Só durante a feira de gado (semanas 33–36)`),once('stockshow')),tip:t(`烤架小游戏 · 名次决定奖金`,`Grill mini-game · prize by placing`,`Minijogo da grelha · prémio conforme a classificação`),run:()=>sc(t(`烧烤比赛`,`The cook-off`,`O concurso`),C.sanangelo,[t(`牲畜展的场馆外面，几十支烧烤队排开阵势，烟把冬天的天熏成了灰色。评委是三个牧场主和一个退休的牛仔竞技骑手。`,`Outside the stock-show grounds, dozens of cook-off teams set up, and their smoke turns the winter sky grey. The judges are three ranchers and a retired rodeo rider.`,`À porta do recinto da feira de gado, dezenas de equipas montam as grelhas e o fumo pinta de cinzento o céu de inverno. Os jurados são três rancheiros e um antigo cavaleiro de rodeo.`)],[
     {t:t(`报名，上烤架`,`Sign up and fire up`,`Inscrever-te e acender a grelha`),fx:()=>{S.flags.tx8_stockshow=1},next:()=>cityGrill(q=>{const T=t(`烧烤比赛`,`The cook-off`,`O concurso`);
       if(q>=1.15){S.cash+=300;S.rep+=4;ONL(5);return say(T,t(`冠军！退休骑手嚼着你的牛肉说：“我在马背上摔了四十年，就为了等这一口。”`,`First place! The retired rider chews your beef and says, "Forty years falling off horses, just waiting for this bite."`,`Primeiro lugar! O antigo cavaleiro mastiga a tua carne e diz: «Quarenta anos a cair de cavalos, só à espera desta dentada.»`),t(`冠军 +$300 · 口碑 +4`,`Champion +$300 · Reputation +4`,`Campeão +$300 · Reputação +4`))}
       if(q>=0.95){S.cash+=120;S.rep+=2;return say(T,t(`第三名。一个牧场主问你蒜和红椒粉是怎么配的，你只告诉了他一半。`,`Third place. A rancher asks how you balance the garlic and paprika; you tell him half of it.`,`Terceiro lugar. Um rancheiro pergunta como equilibras o alho e o colorau; só lhe contas metade.`),t(`第三名 +$120 · 口碑 +2`,`Third place +$120 · Reputation +2`,`Terceiro lugar +$120 · Reputação +2`))}
       stat('oficio',1);return say(T,t(`没进名次。风太大，火一直不稳。旁边一队老头分了你一碗豆子：“西德州的风，谁都不服。”`,`No placing. Too much wind; the fire never settled. A team of old men next door shares a bowl of beans. "West Texas wind don't bow to nobody."`,`Sem classificação. Demasiado vento; o lume nunca assentou. Uma equipa de velhotes ao lado dá-te uma tigela de feijão. «O vento do Oeste do Texas não se verga a ninguém.»`),t(`手艺 +1`,`Craft +1`,`Ofício +1`))})},
     {t:t(`今年不比了`,`Not this year`,`Este ano não`)}])}
  ]},
  {id:'tx8_riverwalk',n:t(`康乔河步道`,`The Concho River Walk`,`O passeio do rio Concho`),acts:[
   {id:'tx8_pearl',n:t(`沿河散步，看河里的“美人鱼”`,`Stroll the river and find the "mermaid"`,`Passear pelo rio e procurar a «sereia»`),cost:1,run:()=>sc(t(`康乔河`,`The Concho`,`O Concho`),C.sanangelo,[t(`河中央有一座美人鱼雕像，坐在石头上，手里捧着一颗珍珠。当地人说，康乔河的河蚌以前能长出粉紫色的淡水珍珠，叫“康乔珍珠”，如今河蚌受保护，不能随便采了。步道边的老人在钓鱼，鸭子排着队过桥。`,`In the middle of the river a mermaid statue sits on a rock holding a pearl. Locals say the Concho's mussels once grew pink and purple freshwater pearls — Concho pearls — though the mussels are protected now and can't be taken freely. Old men fish along the walk; ducks cross the bridge in single file.`,`No meio do rio, uma estátua de sereia sentada numa pedra segura uma pérola. Os locais dizem que os mexilhões do Concho davam pérolas de água doce cor-de-rosa e roxas — as pérolas do Concho — embora agora estejam protegidos e não se possam apanhar à vontade. Velhotes pescam ao longo do passeio; os patos atravessam a ponte em fila.`)],[
     {t:t(`给妈妈拍张美人鱼的照片`,`Send Mum a photo of the mermaid`,`Mandar à mãe uma fotografia da sereia`),fx:()=>{stat('saud',-2);stat('charme',1)},next:()=>say(t(`康乔河`,`The Concho`,`O Concho`),t(`妈妈回了一个字：“美。”过了一会儿又来一条：“比特茹河的那个好看吗？”你回：“没有特茹河好看。”她发来一个笑脸。`,`Mum replies with one word: "Lovely." A while later another: "Prettier than ours on the Tagus?" You write: "Not as pretty as the Tagus." She sends a smiley.`,`A mãe responde com uma palavra: «Linda.» Pouco depois, outra: «Mais bonita do que as do Tejo?» Escreves: «Não tão bonita como o Tejo.» Ela manda um sorriso.`),t(`乡愁 −2 · 魅力 +1`,`Homesickness −2 · Charm +1`,`Saudade −2 · Charme +1`))},
     {t:t(`跟钓鱼的老人学甩竿`,`Learn to cast from the old men fishing`,`Aprender a lançar a cana com os velhotes`),fx:()=>{stat('tex',2)}}])},
   {id:'tx8_rivermarket',n:t(`周末在河边市集摆摊`,`Weekend stall at the riverside market`,`Banca de fim de semana no mercado do rio`),cost:2,req:AND(()=>S.day>=6||t(`只在周末`,`Weekends only`,`Só ao fim de semana`),daily('rivermarket')),tip:t(`卖掉带来的库存`,`Sell the stock you brought`,`Vender a mercadoria que trouxeste`),run:()=>sc(t(`河边市集`,`The riverside market`,`O mercado do rio`),C.sanangelo,[t(`河边的帐篷下卖蜂蜜、山核桃、手工皂和马海毛围巾。你在最边上的一个空位支起烤架。`,`Under tents by the river: honey, pecans, handmade soap, mohair scarves. You set up your grill in the last free spot at the end.`,`Debaixo das tendas junto ao rio: mel, nozes-pecã, sabonetes artesanais, cachecóis de mohair. Montas a grelha no último lugar livre, ao fundo.`)],[
     {t:t(`开卖`,`Open up`,`Abrir a banca`),fx:()=>stamp('rivermarket'),next:()=>pop(t(`河边市集`,`The riverside market`,`O mercado do rio`),10,1.15,`卖围巾的阿姨用一条马海毛围巾换了你两份烤肉。“羊毛换牛肉，”她说，“这才是圣安吉洛的老规矩。”`,`The scarf lady trades you a mohair scarf for two plates. "Wool for beef," she says. "That's the old San Angelo way."`,`A senhora dos cachecóis troca-te um cachecol de mohair por dois pratos. «Lã por carne», diz. «É o costume antigo de San Angelo.»`)},
     {t:t(`算了`,`Never mind`,`Deixa estar`)}])}
  ]}
 ]
},
/* ---------------- ABILENE ---------------- */
abilene:{n:C.abilene,region:'west',miles:190,trip:'overnight',hotel:80,via:['i35','i20'],
 desc:t(`20 号州际公路边的边疆小城：铁路造出来的城，市中心满是童书人物的铜像，三所教会大学，还有天上低低飞过的大轰炸机。`,`A frontier town on I-20: built by the railroad, its downtown full of bronze storybook characters, three church universities, and big bombers flying low overhead.`,`Uma cidade de fronteira junto à I-20: feita pelo caminho de ferro, com o centro cheio de personagens de livros infantis em bronze, três universidades de igrejas e grandes bombardeiros a voar baixinho.`),
 arrive:()=>{if(VIS('abilene')<=1){stat('tex',2);return [t(`过了沃思堡，20 号州际公路一直往西，城越来越小，天越来越大。阿比林的名字是从堪萨斯借来的——那边是当年赶牛路的终点，这边的人希望自己也能成为一个。进城的时候，一架巨大的灰色轰炸机从你头顶低低地飞过，玻璃窗都在震。`,`Past Fort Worth, I-20 runs west, the towns shrinking and the sky growing. Abilene borrowed its name from Kansas — the end of the old cattle trail up there — hoping to become one too. As you come into town, a huge grey bomber passes low over your head and rattles the windows.`,`Depois de Fort Worth, a I-20 segue para oeste, as vilas a encolher e o céu a crescer. Abilene foi buscar o nome ao Kansas — o fim do antigo trilho do gado lá em cima — na esperança de vir a ser um também. À entrada da cidade, um enorme bombardeiro cinzento passa baixinho por cima de ti e faz tremer os vidros.`)]}
  return [inSeason(25,36)?t(`冬天的市中心挂满了灯，铜像们都被人围上了围巾。`,`In winter, lights hang all over downtown and someone has wrapped scarves around the bronzes.`,`No inverno o centro está cheio de luzes e alguém pôs cachecóis às estátuas de bronze.`):t(`铁轨边的老站房还是那么红，一列长长的货车正慢慢经过。`,`The old depot by the tracks is as red as ever; a long freight train rolls slowly by.`,`A velha estação junto aos carris continua vermelha; um comboio de mercadorias comprido passa devagar.`)]},
 locs:[
  {id:'tx8_storybook',n:t(`童书雕塑街区`,`The storybook sculptures downtown`,`As esculturas dos livros infantis no centro`),acts:[
   {id:'tx8_ada',n:t(`找那个坐在铜熊边画画的人`,`Find the woman sketching by the bronze bear`,`Procurar a mulher que desenha ao pé do urso de bronze`),cost:2,req:STAGE('ada','abilene',4),tip:STORYTIP,run:adaScene},
   {id:'tx8_statues',n:t(`一个一个找铜像`,`Hunt down the bronzes one by one`,`Procurar as estátuas uma a uma`),cost:1,run:()=>{const w=W();return sc(t(`童书铜像`,`The storybook bronzes`,`As estátuas dos livros`),C.abilene,[
     t(`游客中心给了你一张地图，上面标着几十座铜像。你在银行门口找到一只穿背心的鼠，在路灯下找到一个骑着书飞的男孩，在喷泉边找到一只长着翅膀的狗。路过的小孩都会摸一摸它们的鼻子，铜鼻子被摸得金亮。`,`The visitor center hands you a map marking dozens of bronzes. Outside a bank you find a mouse in a waistcoat; under a streetlight, a boy flying on a book; by a fountain, a dog with wings. Every passing kid rubs their noses, and the bronze noses have been rubbed to a shine.`,`O centro de visitantes dá-te um mapa com dezenas de estátuas. À porta de um banco encontras um rato de colete; debaixo de um candeeiro, um rapaz a voar num livro; ao pé de uma fonte, um cão com asas. Todas as crianças que passam lhes esfregam o nariz, e os narizes de bronze estão a brilhar de tanto uso.`),
     ...(w?[t(`${SH(w)}找到一只读书的熊，非要你坐在旁边一起拍照。`,`${SH(w)} finds a bear reading a book and insists you sit beside it for a photo together.`,`${SH(w)} encontra um urso a ler e insiste que te sentes ao lado para uma fotografia juntos.`)]:[])],[
     {t:t(`找齐地图上的每一座`,`Find every single one on the map`,`Encontrar todas as do mapa`),fx:()=>{stat('charme',1);stat('saud',-2);if(w)addLike(w,2)}},
     {t:t(`给鲁伊寄一张明信片`,`Mail Rui a postcard`,`Mandar um postal ao Rui`),fx:()=>{stat('saud',-1);stat('tex',1);if(w)addTrust(w,0.5)},next:()=>say(t(`明信片`,`A postcard`,`Um postal`),t(`你写：“这里有一座城，专门给小孩子的故事造铜像。妈妈会喜欢的。”写完你才发现，你已经很久没用“我想回家”结尾了。`,`You write: "There's a town here that casts bronze statues just for children's stories. Mum would love it." Only after do you notice it's been a long time since you ended a card with "I want to come home."`,`Escreves: «Há aqui uma cidade que faz estátuas de bronze só para as histórias das crianças. A mãe ia adorar.» Só depois reparas que há muito tempo que não acabas um postal com «quero voltar para casa».`),t(`乡愁 −1 · 德州味 +1`,`Homesickness −1 · Texanness +1`,`Saudade −1 · Texanidade +1`))}])}}
  ]},
  {id:'tx8_depot',n:t(`老火车站与边疆博物馆`,`The old depot & the frontier museum`,`A velha estação e o museu da fronteira`),acts:[
   {id:'tx8_frontier',n:t(`看边疆历史展`,`See the frontier history exhibit`,`Ver a exposição da fronteira`),cost:1,run:()=>sc(t(`边疆博物馆`,`The frontier museum`,`O museu da fronteira`),C.abilene,[t(`博物馆讲的是这片平原一百多年前的样子：成群的野牛、科曼奇人的骑手、军队的堡垒、赶牛的牛仔、后来的铁路。墙上的投影里，一个老牛仔讲他怎么在暴风雪里赶着三千头牛过河。`,`The museum shows this plain as it was a century and more ago: herds of bison, Comanche riders, army forts, trail-driving cowboys, then the railroad. In a projection on the wall, an old cowboy tells how he drove three thousand head across a river in a blizzard.`,`O museu mostra esta planície como era há mais de cem anos: manadas de bisontes, cavaleiros comanches, fortes do exército, vaqueiros a conduzir gado e depois o caminho de ferro. Numa projeção na parede, um velho cowboy conta como levou três mil cabeças através de um rio no meio de uma nevasca.`)],[
     {t:t(`认真看完`,`Take it all in`,`Ver tudo com atenção`),fx:()=>{stat('tex',3)}},
     {t:t(`跟一位老志愿者聊若泽那代移民`,`Talk with an old volunteer about José's generation of immigrants`,`Conversar com um velho voluntário sobre a geração de imigrantes do José`),fx:()=>{stat('tex',1);stat('saud',1);S.rep+=1},next:()=>say(t(`老志愿者`,`The old volunteer`,`O velho voluntário`),t(`“每一代人来德州，都觉得自己是最后一批拓荒的，”他说，“其实拓荒从来没停过。你就是。”`,`"Every generation that comes to Texas thinks they're the last pioneers," he says. "Truth is, the pioneering never stopped. You're it."`,`«Cada geração que chega ao Texas acha que são os últimos pioneiros», diz. «A verdade é que isso nunca parou. Tu és um.»`),t(`德州味 +1 · 口碑 +1`,`Texanness +1 · Reputation +1`,`Texanidade +1 · Reputação +1`))}])},
   {id:'tx8_depotpop',n:t(`在火车站广场的周六市集摆摊`,`Saturday stall on the depot plaza`,`Banca de sábado na praça da estação`),cost:2,req:AND(()=>S.day===6||t(`只在星期六`,`Saturdays only`,`Só ao sábado`),daily('depotpop')),tip:t(`卖掉库存；空军基地的家庭很爱尝新`,`Sell stock; air-base families love trying new food`,`Vender a mercadoria; as famílias da base aérea gostam de provar coisas novas`),run:()=>sc(t(`火车站广场`,`The depot plaza`,`A praça da estação`),C.abilene,[t(`星期六上午，火车站前的广场上摆满了摊位。很多客人是附近空军基地的家庭，从全国各地调过来，什么都想尝尝。`,`Saturday morning, the plaza in front of the depot is full of stalls. Lots of the customers are families from the nearby air base, posted in from all over the country and keen to try anything.`,`Sábado de manhã, a praça em frente à estação está cheia de bancas. Muitos clientes são famílias da base aérea ali perto, vindas de todo o país e com vontade de provar tudo.`)],[
     {t:t(`开卖`,`Open up`,`Abrir a banca`),fx:()=>stamp('depotpop'),next:()=>pop(t(`火车站广场`,`The depot plaza`,`A praça da estação`),12,1.2,`一位飞行员的妻子说她在亚速尔群岛的空军基地住过三年：“我想这个味道想了十年。”她拍了照片发到基地的家长群里。`,`An airman's wife says she lived three years at the air base in the Azores. "I've missed this taste for ten years." She posts a photo to the base parents' group.`,`A mulher de um militar da Força Aérea diz que viveu três anos na base dos Açores. «Há dez anos que tenho saudades deste sabor.» Publica uma fotografia no grupo de pais da base.`)},
     {t:t(`算了`,`Never mind`,`Deixa estar`)}])}
  ]},
  {id:'tx8_church',n:t(`大学山上的教会大学`,`The church universities on the hill`,`As universidades das igrejas na colina`),acts:[
   {id:'tx8_banquet',n:t(`给一所大学的校友晚宴做外烩`,`Cater a university alumni dinner`,`Fazer o catering de um jantar de antigos alunos`),cost:3,req:AND(once('banquet'),()=>charm()+formalPenalty()>=50||NEED(t(`正式场合魅力 50（口音会影响）`,`Formal charm 50 (accent counts)`,`Charme formal 50 (o sotaque conta)`))),tip:t(`一次性大单 · 正式场合`,`One big order · formal occasion`,`Uma encomenda grande · ocasião formal`),run:()=>sc(t(`校友晚宴`,`The alumni dinner`,`O jantar de antigos alunos`),C.abilene,[t(`晚宴在一座有彩色玻璃窗的礼堂里，客人穿着西装和长裙，开饭前要祷告。负责人是位一丝不苟的女士：“不要酒，不要太辣，八点整上主菜。”`,`The dinner is in a hall with stained-glass windows; the guests wear suits and long dresses, and there's grace before the meal. The organizer is a very precise lady. "No alcohol, nothing too spicy, main course at eight sharp."`,`O jantar é num salão com vitrais; os convidados vêm de fato e vestido comprido, e há uma oração antes da refeição. A organizadora é uma senhora muito rigorosa. «Nada de álcool, nada muito picante, prato principal às oito em ponto.»`)],[
     {t:t(`按她的要求，一分不差`,`Do exactly as she asks, to the minute`,`Fazer exatamente o que pede, ao minuto`),fx:()=>{S.flags.tx8_banquet=1;S.cash+=320;S.wk.rev+=320;S.rep+=3;ONL(3);if(MET('dale'))addTrust('dale',1);log('阿比林校友晚宴外烩 +$320','Catered an Abilene alumni dinner +$320','Catering de um jantar de antigos alunos em Abilene +$320')},next:()=>say(t(`校友晚宴`,`The alumni dinner`,`O jantar de antigos alunos`),[t(`八点整，一百份蒜香猪里脊同时上桌。负责人看了看表，第一次笑了。散场时三个人来要你的电话，一个说他儿子下个月在你们那边结婚。`,`At eight sharp, a hundred plates of garlic pork loin hit the tables at once. The organizer checks her watch and smiles for the first time. As people leave, three ask for your number; one says his son is getting married near your town next month.`,`Às oito em ponto, cem pratos de lombo de porco com alho chegam às mesas ao mesmo tempo. A organizadora olha para o relógio e sorri pela primeira vez. À saída, três pessoas pedem-te o número; uma diz que o filho se casa perto da tua terra no mês que vem.`),...(MET('dale')?[t(`有位老先生说他认识戴尔·金凯德牧师：“替我问候他，告诉他阿比林还记得他唱歌跑调。”`,`An old gentleman says he knows Pastor Dale Kincaid. "Give him my regards and tell him Abilene still remembers him singing off-key."`,`Um senhor de idade diz que conhece o Pastor Dale Kincaid. «Dá-lhe cumprimentos e diz-lhe que Abilene ainda se lembra dele a cantar desafinado.»`)]:[])],t(`现金 +$320 · 口碑 +3`,`Cash +$320 · Reputation +3`,`Dinheiro +$320 · Reputação +3`))},
     {t:t(`算了，这种场合你会紧张`,`Pass — occasions like this make you nervous`,`Não — estas ocasiões deixam-te nervoso`)}])},
   {id:'tx8_buffalogap',n:t(`去城南的野牛谷老村`,`Drive south to the Buffalo Gap historic village`,`Ir à aldeia histórica de Buffalo Gap, a sul`),cost:2,run:()=>sc(t(`野牛谷`,`Buffalo Gap`,`Buffalo Gap`),C.abilene,[t(`城南十几英里，两座小山之间的缺口，当年野牛从这里迁徙经过。老村里保留着十九世纪的石头法院、铁匠铺和一间只有一个教室的学校。铁匠正在打马蹄铁，火星溅到地上。`,`A dozen-odd miles south of town, a gap between two hills where the bison once migrated through. The historic village keeps a nineteenth-century stone courthouse, a blacksmith's shop and a one-room schoolhouse. The smith is shaping a horseshoe; sparks spatter the ground.`,`Uma dúzia de milhas a sul da cidade, uma brecha entre duas colinas por onde os bisontes migravam. A aldeia histórica guarda um tribunal de pedra do século XIX, uma ferraria e uma escola de uma só sala. O ferreiro está a forjar uma ferradura; as faíscas salpicam o chão.`)],[
     {t:t(`请铁匠帮你修烤架的铁钩`,`Ask the smith to fix the iron hooks of your grill`,`Pedir ao ferreiro que arranje os ganchos de ferro da tua grelha`),fx:()=>{stat('oficio',2);stat('tex',1)},next:()=>say(t(`铁匠铺`,`The smithy`,`A ferraria`),t(`他把钩子放进火里，敲了几下，又在水里一淬，滋的一声。“这钩子是手打的，起码三十年了。”你想起若泽的手。`,`He puts the hooks in the fire, gives them a few blows, quenches them with a hiss. "These were hand-forged. Thirty years old at least." You think of José's hands.`,`Mete os ganchos no lume, dá-lhes umas marteladas e tempera-os na água com um silvo. «Isto foi forjado à mão. Tem pelo menos trinta anos.» Pensas nas mãos do José.`),t(`手艺 +2 · 德州味 +1`,`Craft +2 · Texanness +1`,`Ofício +2 · Texanidade +1`))},
     {t:t(`坐在老学校的长凳上`,`Sit on a bench in the old schoolhouse`,`Sentar num banco da velha escola`),fx:()=>{stat('saud',1);stat('charme',1)}}])}
  ]}
 ]
},
/* ---------------- DEL RIO & SEMINOLE CANYON ---------------- */
delrio:{n:t(`德尔里奥与锡米诺尔峡谷`,`Del Rio & Seminole Canyon`,`Del Rio e Seminole Canyon`),region:'west',miles:250,trip:'overnight',hotel:85,via:['i35','us90'],
 desc:t(`格兰德河边的边境小城：一股从不断流的泉水、蓝绿色的阿米斯塔德水库、几千年前画在岩棚里的人形，和高高架在佩科斯河上的大桥。`,`A border town on the Rio Grande: a spring that has never stopped flowing, the blue-green Amistad Reservoir, human figures painted in rock shelters thousands of years ago, and a bridge set high over the Pecos.`,`Uma cidade de fronteira junto ao rio Grande: uma nascente que nunca parou de correr, a albufeira azul-esverdeada de Amistad, figuras humanas pintadas em abrigos rochosos há milhares de anos e uma ponte bem alta sobre o Pecos.`),
 arrive:()=>{if(VIS('delrio')<=1){stat('saud',-2);stat('tex',2);return [t(`从圣安东尼奥上 90 号国道往西，路越来越空，偶尔有一列火车和你并排跑一阵。进了德尔里奥，街边是老石头房子和山核桃树，河对岸就是墨西哥的阿库尼亚城。三十年代，河那边有过一座大功率电台，人们常说半个美洲夜里都能听到它。`,`From San Antonio, US-90 heads west, emptier and emptier; now and then a train runs alongside you for a while. In Del Rio the streets are old stone houses and pecan trees, and across the river is Ciudad Acuña in Mexico. In the thirties there was a huge radio station over there; folks say half the Americas could hear it at night.`,`De San Antonio, a US-90 segue para oeste, cada vez mais vazia; de vez em quando um comboio corre ao teu lado durante um bocado. Em Del Rio as ruas são casas velhas de pedra e nogueiras-pecã, e do outro lado do rio fica Ciudad Acuña, no México. Nos anos trinta havia lá uma rádio enorme; diz-se que metade das Américas a ouvia à noite.`)]}
  return [inSeason(1,12)?t(`夏天热得像烤炉，连格兰德河都懒洋洋的。`,`Summer heat like an oven; even the Rio Grande looks lazy.`,`Um calor de verão de forno; até o rio Grande parece preguiçoso.`):t(`泉水还是那么清，街边的山核桃树又结果了。`,`The spring is as clear as ever and the pecan trees along the street are bearing again.`,`A nascente continua límpida e as nogueiras da rua voltaram a dar fruto.`)]},
 locs:[
  {id:'tx8_canyon',n:t(`锡米诺尔峡谷州立公园`,`Seminole Canyon State Park`,`Parque Estadual de Seminole Canyon`),acts:[
   {id:'tx8_lupe',n:t(`跟着志愿向导下到岩棚`,`Follow the volunteer guide down to the shelter`,`Seguir a guia voluntária até ao abrigo`),cost:2,req:STAGE('lupe','delrio',4),tip:STORYTIP,run:lupeScene},
   {id:'tx8_rim',n:t(`在峡谷边缘看日落`,`Watch the sunset from the canyon rim`,`Ver o pôr do sol na borda do desfiladeiro`),cost:1,run:()=>{const w=W();return sc(t(`峡谷边缘`,`The canyon rim`,`A borda do desfiladeiro`),C.delrio,[
     t(`太阳落下去的时候，石灰岩从白变成金，又从金变成粉红。峡谷底下有一丛丛的龙舌兰和丝兰，一只走鹃从小路上跑过去，停下来看了你一眼。天黑以后，星星多得吓人。`,`As the sun goes down the limestone turns from white to gold, then gold to pink. Clumps of agave and yucca stand on the canyon floor; a roadrunner dashes along the trail, stops and gives you a look. After dark there are frightening numbers of stars.`,`Quando o sol se põe, o calcário passa de branco a dourado e de dourado a cor-de-rosa. No fundo do desfiladeiro há tufos de agave e iúca; um corredor-da-estrada atravessa o trilho a correr, para e olha para ti. Depois de escurecer há estrelas a mais, de assustar.`),
     ...(w?[t(`${SH(w)}靠在你肩上，数到第一百颗星星就放弃了。`,`${SH(w)} leans on your shoulder and gives up counting stars at a hundred.`,`${SH(w)} encosta-se ao teu ombro e desiste de contar as estrelas ao chegar às cem.`)]:[t(`你一个人躺在石头上，觉得自己很小，小得很舒服。`,`You lie alone on the rock and feel very small, comfortably small.`,`Ficas deitado sozinho na pedra e sentes-te muito pequeno, confortavelmente pequeno.`)])],[
     {t:t(`一直待到看见银河`,`Stay until you can see the Milky Way`,`Ficar até veres a Via Láctea`),fx:()=>{stat('saud',-3);stat('charme',1);if(w){addLike(w,2);addTrust(w,1)}}},
     {t:t(`拍一张照片给妈妈`,`Take a photo for Mum`,`Tirar uma fotografia para a mãe`),fx:()=>{stat('saud',-1);if(w)addLike(w,1)}}])}}
  ]},
  {id:'tx8_amistad',n:t(`阿米斯塔德水库`,`Amistad Reservoir`,`Albufeira de Amistad`),acts:[
   {id:'tx8_lakefish',n:t(`跟湖边的渔民买鱼`,`Buy fish from the lake fishermen`,`Comprar peixe aos pescadores do lago`),cost:1,req:daily('lakefish'),run:()=>sc(t(`湖边`,`The lakeshore`,`A margem do lago`),C.delrio,[t(`清晨的码头上，几个渔民把夜里钓的鱼摊在冰上。这个湖以鲈鱼出名，从全国各地来的钓鱼人开着船拖车排队下水。`,`On the early-morning dock a few fishermen lay out last night's catch on ice. The lake is famous for bass, and anglers from all over the country queue with their boat trailers at the ramp.`,`No cais de madrugada, uns pescadores espalham sobre o gelo o peixe da noite. O lago é famoso pelo achigã, e pescadores de todo o país fazem fila com os atrelados dos barcos na rampa.`)],[
     {t:t(`拿 10 份鱼（七折）`,`Take 10 fish (30% off)`,`Levar 10 de peixe (30% de desconto)`),fx:()=>stamp('lakefish'),next:()=>buy(t(`湖边`,`The lakeshore`,`A margem do lago`),'fish',10,0.7,`你挑鱼的时候用手指按鱼眼和鱼腮。老渔民用西语跟同伴说：“这个外国人懂。”`,`You check the eyes and gills with your fingers as you pick. An old fisherman says to his friend in Spanish, "This foreigner knows his stuff."`,`Ao escolheres, verificas os olhos e as guelras com os dedos. Um velho pescador diz ao companheiro em espanhol: «Este estrangeiro percebe disto.»`)},
     {t:t(`只看看`,`Just look`,`Só ver`)}])},
   {id:'tx8_dam',n:t(`开车上大坝，站在国境线上`,`Drive onto the dam and stand on the border line`,`Ir à barragem e pôr-te em cima da fronteira`),cost:1,run:()=>{const w=W();return sc(t(`友谊大坝`,`Amistad Dam`,`A barragem de Amistad`),C.delrio,[
     t(`大坝是两国一起修的，中间有一条线：这边是美国，那边是墨西哥。你一只脚站在一边。风从湖上吹过来，两个国家的风是一样的。`,`The dam was built by both countries together, and there's a line in the middle: this side the United States, that side Mexico. You stand with one foot on each. The wind comes off the lake, and it's the same wind on both sides.`,`A barragem foi construída pelos dois países juntos e há uma linha a meio: deste lado os Estados Unidos, do outro o México. Pões um pé de cada lado. O vento vem do lago e é o mesmo vento dos dois lados.`),
     ...(w==='ines'?[t(`伊内丝说：“你看，两个国家，一个湖。你也可以两边都是。”`,`Inês says, "Look — two countries, one lake. You can be both, too."`,`A Inês diz: «Vês? Dois países, um lago. Tu também podes ser as duas coisas.»`)]:w?[t(`${SH(w)}也站上来，一只脚在美国，一只脚在墨西哥，冲你做了个鬼脸。`,`${SH(w)} steps up too, one foot in the US and one in Mexico, and pulls a face at you.`,`${SH(w)} também se põe ali, um pé nos Estados Unidos e outro no México, e faz-te uma careta.`)]:[])],[
     {t:t(`想一想：你到底属于哪一边？`,`Think about it: which side do you belong to?`,`Pensar: afinal a que lado pertences?`),fx:()=>{stat('saud',1);stat('tex',2);if(w)addTrust(w,1)}},
     {t:t(`拍张照，配文“两只脚，两个家”`,`Take a photo captioned "Two feet, two homes"`,`Tirar uma fotografia com a legenda «Dois pés, duas casas»`),fx:()=>{ONL(2);stat('charme',1);if(w)addLike(w,1)}}])}}
  ]},
  {id:'tx8_town',n:t(`德尔里奥老城与圣费利佩泉`,`Old Del Rio & San Felipe Springs`,`O centro de Del Rio e as nascentes de San Felipe`),acts:[
   {id:'tx8_springs',n:t(`在泉水边乘凉`,`Cool off by the springs`,`Refrescar-te junto às nascentes`),cost:1,run:()=>sc(t(`圣费利佩泉`,`San Felipe Springs`,`Nascentes de San Felipe`),C.delrio,[t(`泉水从石灰岩里冒出来，清得能看到水底的每一颗石子，流进一条老水渠，穿过城里的院子和菜园。几百年来，这股水让沙漠边上长出了一座城。孩子们在溪里扑腾，老人坐在树荫下下棋。`,`The springs well up out of the limestone, clear enough to see every pebble on the bottom, and run into an old irrigation canal through the town's yards and gardens. For centuries this water has let a town grow on the desert's edge. Kids splash in the creek; old men play checkers in the shade.`,`As nascentes brotam do calcário, tão límpidas que se vê cada seixo do fundo, e correm para um velho canal de rega que atravessa os quintais e as hortas da cidade. Há séculos que esta água deixa crescer uma cidade à beira do deserto. Os miúdos chapinham no ribeiro; os velhos jogam damas à sombra.`)],[
     {t:t(`把脚泡进水里`,`Put your feet in the water`,`Pôr os pés na água`),fx:()=>{stat('saud',-2);stat('charme',1)}},
     {t:t(`跟下棋的老人下一盘`,`Play a game with the old men`,`Jogar uma partida com os velhotes`),fx:()=>{stat('tex',2);S.rep+=1},next:()=>say(t(`树荫下`,`In the shade`,`À sombra`),t(`你输了。老人说：“下次带你的烤肉来，我让你赢一次。”`,`You lose. The old man says, "Bring your barbecue next time and I'll let you win one."`,`Perdes. O velho diz: «Traz o teu churrasco da próxima vez e deixo-te ganhar uma.»`),t(`德州味 +2 · 口碑 +1`,`Texanness +2 · Reputation +1`,`Texanidade +2 · Reputação +1`))}])},
   {id:'tx8_airbase',n:t(`给空军基地的毕业典礼做外烩`,`Cater an air-base pilot graduation`,`Fazer o catering de uma formatura de pilotos na base aérea`),cost:3,req:AND(once('airbase'),()=>S.rep>=25||S.stats.oficio>=45||NEED(t(`口碑 25 或手艺 45`,`Reputation 25 or Craft 45`,`Reputação 25 ou Ofício 45`))),tip:t(`一次性大单`,`One big order`,`Uma encomenda grande`),run:()=>sc(t(`飞行员毕业`,`Pilot graduation`,`Formatura de pilotos`),C.delrio,[t(`城东的空军基地是训练飞行员的地方，天上整天有教练机在转圈。一批学员毕业，家长们从全国各地赶来。一位母亲在泉水边吃过你的东西，问你能不能给毕业后的聚会做饭。`,`The air base east of town trains pilots; trainer jets circle overhead all day. A class is graduating and parents have flown in from all over the country. A mother who ate your food by the springs asks if you'll cook for the after-party.`,`A base aérea a leste da cidade forma pilotos; os aviões de instrução andam às voltas o dia todo. Há um curso a terminar e os pais vieram de todo o país. Uma mãe que comeu a tua comida junto às nascentes pergunta se cozinhas para a festa depois da cerimónia.`)],[
     {t:t(`接下：六十个人的庆功宴`,`Take it: a celebration for sixty`,`Aceitar: uma festa para sessenta`),fx:()=>{S.flags.tx8_airbase=1;S.cash+=420;S.wk.rev+=420;S.rep+=3;ONL(4);stat('charme',1);log('德尔里奥飞行员毕业外烩 +$420','Catered a Del Rio pilot graduation +$420','Catering da formatura de pilotos em Del Rio +$420')},next:()=>say(t(`飞行员毕业`,`Pilot graduation`,`Formatura de pilotos`),t(`年轻的飞行员们把帽子扔到天上，然后扑向你的烤肉。一个学员说他下一站要飞去葡萄牙参加演习：“我会想起这顿饭的。”你在他的餐巾上写了一家阿尔法马小馆的地址。`,`The young pilots throw their caps in the air, then fall on your grill. One cadet says his next posting takes him to an exercise in Portugal. "I'll think of this meal." You write the address of a little Alfama tasca on his napkin.`,`Os jovens pilotos atiram os bonés ao ar e depois atiram-se à tua grelha. Um cadete diz que o próximo destino é um exercício em Portugal. «Vou lembrar-me desta refeição.» Escreves-lhe no guardanapo a morada de uma tasca de Alfama.`),t(`现金 +$420 · 口碑 +3`,`Cash +$420 · Reputation +3`,`Dinheiro +$420 · Reputação +3`))},
     {t:t(`算了`,`Never mind`,`Deixa estar`)}])}
  ]}
 ]
}
});

/* ---------------- road: sand trucks on I-20 ---------------- */
ROAD_EVENTS.push({id:'tx8_sandconvoy',cond:c=>!!(c.via&&c.via.includes('i20'))&&ST('jesse')>=1,run:c=>sc(t(`砂车车队`,`The sand convoy`,`O comboio de areia`),t(`20 号州际公路`,`I-20`,`I-20`),[
  t(`20 号州际公路上，一列拉砂的半挂车从对面开过来，一辆接一辆，篷布在风里啪啪响。你数到第十四辆，有一辆冲你闪了两下大灯。车门上画着一颗星星。`,`On I-20 a line of sand haulers comes the other way, one after another, tarps snapping in the wind. You count fourteen, and one flashes its headlights at you twice. There's a star painted on its door.`,`Na I-20 vem em sentido contrário uma fila de camiões de areia, um atrás do outro, com as lonas a estalar ao vento. Contas catorze, e um faz-te sinal de luzes duas vezes. Tem uma estrela pintada na porta.`),
  ...(S.flags.tx8_sand?[t(`你想起那些货单上的目的地：圣鲁伊斯，罐头厂路。这些砂，有一天也可能堆在你的店后面。`,`You think of the destination on those bills of lading: San Luís, Packing Co. Road. One day this sand could be piled up behind your shop.`,`Pensas no destino daquelas guias: San Luís, Packing Co. Road. Um dia esta areia pode estar empilhada atrás do teu restaurante.`)]:[])],[
  {t:t(`闪灯回应他`,`Flash your lights back`,`Responder com as luzes`),fx:()=>{if(MET('jesse'))addLike('jesse',1);stat('tex',1)}},
  {t:t(`默默记下车牌和时间`,`Quietly note the plates and the time`,`Anotar em silêncio as matrículas e a hora`),fx:()=>{stat('tex',1);S.flags.tx8_convoyLog=1}}])});
})();
